func minSubArrayLen(target int, nums []int) int {
	l, sum, best := 0, 0, len(nums)+1
	for r, x := range nums {
		sum += x
		for sum >= target {
			best = min(best, r-l+1)
			sum -= nums[l]
			l++
		}
	}
	if best > len(nums) {
		return 0
	}
	return best
}

