func findAnagrams(s, p string) []int {
	want, have := [26]int{}, [26]int{}
	for i := range p {
		want[p[i]-'a']++
	}
	ans := []int{}
	for r := range s {
		have[s[r]-'a']++
		if r >= len(p) {
			have[s[r-len(p)]-'a']--
		}
		if r+1 >= len(p) && have == want {
			ans = append(ans, r-len(p)+1)
		}
	}
	return ans
}

