func checkInclusion(s1, s2 string) bool {
	want, have := [26]int{}, [26]int{}
	for i := range s1 {
		want[s1[i]-'a']++
	}
	if len(s1) == 0 {
		return true
	}
	for r := range s2 {
		have[s2[r]-'a']++
		if r >= len(s1) {
			have[s2[r-len(s1)]-'a']--
		}
		if r+1 >= len(s1) && have == want {
			return true
		}
	}
	return false
}

