func pathSum(root *TreeNode, targetSum int) int {
	freq := map[int64]int{0: 1}
	var dfs func(*TreeNode, int64) int
	dfs = func(n *TreeNode, s int64) int {
		if n == nil {
			return 0
		}
		s += int64(n.Val)
		ans := freq[s-int64(targetSum)]
		freq[s]++
		ans += dfs(n.Left, s) + dfs(n.Right, s)
		freq[s]--
		return ans
	}
	return dfs(root, 0)
}

