func reverseBetween(head *ListNode, left, right int) *ListNode {
	dummy := &ListNode{Next: head}
	pre := dummy
	for i := 1; i < left; i++ {
		pre = pre.Next
	}
	tail := pre.Next
	for i := 0; i < right-left; i++ {
		x := tail.Next
		tail.Next = x.Next
		x.Next = pre.Next
		pre.Next = x
	}
	return dummy.Next
}

reverse-nodes-in-k-group.go:
func reverseKGroup(head *ListNode, k int) *ListNode {
	dummy := &ListNode{Next: head}
	pre := dummy
	for {
		end := pre
		for i := 0; i < k && end != nil; i++ {
			end = end.Next
		}
		if end == nil {
			break
		}
		after := end.Next
		old := pre.Next
		prev, cur := after, old
		for cur != after {
			next := cur.Next
			cur.Next = prev
			prev = cur
			cur = next
		}
		pre.Next = end
		pre = old
	}
	return dummy.Next
}

