func isPalindrome(head *ListNode) bool {
	if head == nil {
		return true
	}
	s, f := head, head
	for f.Next != nil && f.Next.Next != nil {
		s = s.Next
		f = f.Next.Next
	}
	rev := func(n *ListNode) *ListNode {
		var p *ListNode
		for n != nil {
			x := n.Next
			n.Next = p
			p = n
			n = x
		}
		return p
	}
	second := rev(s.Next)
	a, b := head, second
	ok := true
	for b != nil {
		if a.Val != b.Val {
			ok = false
		}
		a = a.Next
		b = b.Next
	}
	s.Next = rev(second)
	return ok
}

