func addTwoNumbers(a, b *ListNode) *ListNode {
	d := &ListNode{}
	t := d
	carry := 0
	for a != nil || b != nil || carry > 0 {
		s := carry
		if a != nil {
			s += a.Val
			a = a.Next
		}
		if b != nil {
			s += b.Val
			b = b.Next
		}
		t.Next = &ListNode{Val: s % 10}
		t = t.Next
		carry = s / 10
	}
	return d.Next
}

