func addTwoNumbers(a, b *ListNode) *ListNode {
	x, y := []int{}, []int{}
	for ; a != nil; a = a.Next {
		x = append(x, a.Val)
	}
	for ; b != nil; b = b.Next {
		y = append(y, b.Val)
	}
	var head *ListNode
	carry := 0
	for len(x) > 0 || len(y) > 0 || carry > 0 {
		s := carry
		if len(x) > 0 {
			s += x[len(x)-1]
			x = x[:len(x)-1]
		}
		if len(y) > 0 {
			s += y[len(y)-1]
			y = y[:len(y)-1]
		}
		head = &ListNode{Val: s % 10, Next: head}
		carry = s / 10
	}
	return head
}

