func searchRange(nums []int, target int) []int {
	bound := func(strict bool) int {
		l, r := 0, len(nums)
		for l < r {
			m := l + (r-l)/2
			if nums[m] < target || (strict && nums[m] == target) {
				l = m + 1
			} else {
				r = m
			}
		}
		return l
	}
	a := bound(false)
	if a == len(nums) || nums[a] != target {
		return []int{-1, -1}
	}
	return []int{a, bound(true) - 1}
}

