import "math"

func findMedianSortedArrays(a, b []int) float64 {
	if len(a) > len(b) {
		return findMedianSortedArrays(b, a)
	}
	l, r := 0, len(a)
	for l <= r {
		i := l + (r-l)/2
		j := (len(a)+len(b)+1)/2 - i
		al, ar, bl, br := math.Inf(-1), math.Inf(1), math.Inf(-1), math.Inf(1)
		if i > 0 {
			al = float64(a[i-1])
		}
		if i < len(a) {
			ar = float64(a[i])
		}
		if j > 0 {
			bl = float64(b[j-1])
		}
		if j < len(b) {
			br = float64(b[j])
		}
		if al > br {
			r = i - 1
		} else if bl > ar {
			l = i + 1
		} else {
			if (len(a)+len(b))%2 == 1 {
				return math.Max(al, bl)
			}
			return (math.Max(al, bl) + math.Min(ar, br)) / 2
		}
	}
	return 0
}

