func isBalanced(root *TreeNode) bool {
	var h func(*TreeNode) int
	h = func(n *TreeNode) int {
		if n == nil {
			return 0
		}
		l := h(n.Left)
		if l < 0 {
			return -1
		}
		r := h(n.Right)
		if r < 0 || l-r > 1 || r-l > 1 {
			return -1
		}
		return 1 + max(l, r)
	}
	return h(root) >= 0
}

