func cloneGraph(node *Node) *Node {
	copies := map[*Node]*Node{}
	var dfs func(*Node) *Node
	dfs = func(n *Node) *Node {
		if n == nil {
			return nil
		}
		if c, ok := copies[n]; ok {
			return c
		}
		c := &Node{Val: n.Val}
		copies[n] = c
		for _, v := range n.Neighbors {
			c.Neighbors = append(c.Neighbors, dfs(v))
		}
		return c
	}
	return dfs(node)
}

