func floodFill(image [][]int, sr, sc, color int) [][]int {
	old := image[sr][sc]
	if old == color {
		return image
	}
	var dfs func(int, int)
	dfs = func(r, c int) {
		if r < 0 || r >= len(image) || c < 0 || c >= len(image[0]) || image[r][c] != old {
			return
		}
		image[r][c] = color
		dfs(r-1, c)
		dfs(r+1, c)
		dfs(r, c-1)
		dfs(r, c+1)
	}
	dfs(sr, sc)
	return image
}

