func orangesRotting(grid [][]int) int {
	if len(grid) == 0 {
		return 0
	}
	m, n := len(grid), len(grid[0])
	q := [][2]int{}
	fresh := 0
	for r := 0; r < m; r++ {
		for c := 0; c < n; c++ {
			if grid[r][c] == 2 {
				q = append(q, [2]int{r, c})
			} else if grid[r][c] == 1 {
				fresh++
			}
		}
	}
	minutes := 0
	dirs := [][2]int{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}
	for fresh > 0 && len(q) > 0 {
		size := len(q)
		for i := 0; i < size; i++ {
			v := q[0]
			q = q[1:]
			for _, d := range dirs {
				r, c := v[0]+d[0], v[1]+d[1]
				if r >= 0 && r < m && c >= 0 && c < n && grid[r][c] == 1 {
					grid[r][c] = 2
					fresh--
					q = append(q, [2]int{r, c})
				}
			}
		}
		minutes++
	}
	if fresh > 0 {
		return -1
	}
	return minutes
}

word-ladder.go:
func ladderLength(beginWord, endWord string, wordList []string) int {
	dict := map[string]bool{}
	for _, w := range wordList {
		dict[w] = true
	}
	if !dict[endWord] {
		return 0
	}
	delete(dict, beginWord)
	q := []string{beginWord}
	steps := 1
	for len(q) > 0 {
		size := len(q)
		for i := 0; i < size; i++ {
			w := q[0]
			q = q[1:]
			if w == endWord {
				return steps
			}
			b := []byte(w)
			for j, old := range b {
				for c := byte('a'); c <= 'z'; c++ {
					b[j] = c
					s := string(b)
					if dict[s] {
						delete(dict, s)
						q = append(q, s)
					}
				}
				b[j] = old
			}
		}
		steps++
	}
	return 0
}

