	g := make([][]int, n)
	in := make([]int, n)
	for _, e := range prerequisites {
		g[e[1]] = append(g[e[1]], e[0])
		in[e[0]]++
	}
	q := []int{}
	for v, d := range in {
		if d == 0 {
			q = append(q, v)
		}
	}
	for i := 0; i < len(q); i++ {
		for _, w := range g[q[i]] {
			in[w]--
			if in[w] == 0 {
				q = append(q, w)
			}
		}
	}
	if len(q) != n {
		return []int{}
	}
	return q
}
