func eventualSafeNodes(graph [][]int) []int {
	n := len(graph)
	rev := make([][]int, n)
	out := make([]int, n)
	for v, edges := range graph {
		out[v] = len(edges)
		for _, w := range edges {
			rev[w] = append(rev[w], v)
		}
	}
	q := []int{}
	for v, d := range out {
		if d == 0 {
			q = append(q, v)
		}
	}
	for i := 0; i < len(q); i++ {
		for _, v := range rev[q[i]] {
			out[v]--
			if out[v] == 0 {
				q = append(q, v)
			}
		}
	}
	ans := []int{}
	for v, d := range out {
		if d == 0 {
			ans = append(ans, v)
		}
	}
	return ans
}

