	if a == b {
		return false
	}
	if u.size[a] < u.size[b] {
		a, b = b, a
	}
	u.p[b] = a
	u.size[a] += u.size[b]
	return true
}
func accountsMerge(accounts [][]string) [][]string {
	ids := map[string]int{}
	names := map[string]string{}
	for _, a := range accounts {
		for _, e := range a[1:] {
			if _, ok := ids[e]; !ok {
				ids[e] = len(ids)
			}
			names[e] = a[0]
		}
	}
	u := newUF(len(ids))
	for _, a := range accounts {
		for _, e := range a[2:] {
			u.join(ids[a[1]], ids[e])
		}
	}
	groups := map[int][]string{}
	for e, id := range ids {
		r := u.find(id)
		groups[r] = append(groups[r], e)
	}
	ans := [][]string{}
	for _, emails := range groups {
		sort.Strings(emails)
		row := append([]string{names[emails[0]]}, emails...)
		ans = append(ans, row)
	}
	return ans
}

network-delay-time.go:
import "container/heap"

type state struct{ v, d int }
type priority []state

func (h priority) Len() int           { return len(h) }
func (h priority) Less(i, j int) bool { return h[i].d < h[j].d }
func (h priority) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *priority) Push(x any)        { *h = append(*h, x.(state)) }
func (h *priority) Pop() any          { a := *h; x := a[len(a)-1]; *h = a[:len(a)-1]; return x }
func networkDelayTime(times [][]int, n, k int) int {
	g := make([][]state, n+1)
	for _, e := range times {
		g[e[0]] = append(g[e[0]], state{e[1], e[2]})
	}
	inf := int(^uint(0) >> 1)
	dist := make([]int, n+1)
	for i := 1; i <= n; i++ {
		dist[i] = inf
	}
	dist[k] = 0
	h := &priority{{k, 0}}
	for h.Len() > 0 {
		s := heap.Pop(h).(state)
		if s.d != dist[s.v] {
			continue
		}
		for _, e := range g[s.v] {
			d := s.d + e.d
			if d < dist[e.v] {
				dist[e.v] = d
				heap.Push(h, state{e.v, d})
			}
		}
	}
	ans := 0
	for i := 1; i <= n; i++ {
		if dist[i] == inf {
			return -1
		}
		ans = max(ans, dist[i])
	}
	return ans
}

path-with-minimum-effort.go:
import "container/heap"

type state struct{ v, d int }
type priority []state

func (h priority) Len() int           { return len(h) }
func (h priority) Less(i, j int) bool { return h[i].d < h[j].d }
func (h priority) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *priority) Push(x any)        { *h = append(*h, x.(state)) }
func (h *priority) Pop() any          { a := *h; x := a[len(a)-1]; *h = a[:len(a)-1]; return x }
func minimumEffortPath(heights [][]int) int {
	m, n := len(heights), len(heights[0])
	inf := int(^uint(0) >> 1)
	dist := make([]int, m*n)
	for i := range dist {
		dist[i] = inf
	}
	dist[0] = 0
	h := &priority{{0, 0}}
	dirs := [][2]int{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}
	for h.Len() > 0 {
		s := heap.Pop(h).(state)
		if s.d != dist[s.v] {
			continue
		}
		if s.v == m*n-1 {
			return s.d
		}
		r, c := s.v/n, s.v%n
		for _, d := range dirs {
			a, b := r+d[0], c+d[1]
			if a < 0 || a >= m || b < 0 || b >= n {
				continue
			}
			delta := heights[a][b] - heights[r][c]
			if delta < 0 {
				delta = -delta
			}
			nd := max(s.d, delta)
			v := a*n + b
			if nd < dist[v] {
				dist[v] = nd
				heap.Push(h, state{v, nd})
			}
		}
	}
	return 0
}

