func validArrangement(pairs [][]int) [][]int {
	g := map[int][]int{}
	balance := map[int]int{}
	for _, e := range pairs {
		g[e[0]] = append(g[e[0]], e[1])
		balance[e[0]]++
		balance[e[1]]--
	}
	start := pairs[0][0]
	for v, d := range balance {
		if d == 1 {
			start = v
		}
	}
	st := []int{start}
	path := []int{}
	for len(st) > 0 {
		v := st[len(st)-1]
		a := g[v]
		if len(a) == 0 {
			path = append(path, v)
			st = st[:len(st)-1]
		} else {
			w := a[len(a)-1]
			g[v] = a[:len(a)-1]
			st = append(st, w)
		}
	}
	ans := [][]int{}
	for i := len(path) - 1; i > 0; i-- {
		ans = append(ans, []int{path[i], path[i-1]})
	}
	return ans
}

