import "strings"

func solveNQueens(n int) [][]string {
	ans := [][]string{}
	cols := make([]bool, n)
	d1, d2 := make([]bool, 2*n), make([]bool, 2*n)
	path := make([]int, n)
	var dfs func(int)
	dfs = func(r int) {
		if r == n {
			board := make([]string, n)
			for i, c := range path {
				board[i] = strings.Repeat(".", c) + "Q" + strings.Repeat(".", n-c-1)
			}
			ans = append(ans, board)
			return
		}
		for c := 0; c < n; c++ {
			a, b := r-c+n, r+c
			if cols[c] || d1[a] || d2[b] {
				continue
			}
			cols[c], d1[a], d2[b] = true, true, true
			path[r] = c
			dfs(r + 1)
			cols[c], d1[a], d2[b] = false, false, false
		}
	}
	dfs(0)
	return ans
}

