func exist(board [][]byte, word string) bool {
	if len(word) == 0 {
		return true
	}
	if len(board) == 0 {
		return false
	}
	var dfs func(int, int, int) bool
	dfs = func(r, c, i int) bool {
		if r < 0 || r >= len(board) || c < 0 || c >= len(board[0]) || board[r][c] != word[i] {
			return false
		}
		if i == len(word)-1 {
			return true
		}
		old := board[r][c]
		board[r][c] = 0
		ok := dfs(r-1, c, i+1) || dfs(r+1, c, i+1) || dfs(r, c-1, i+1) || dfs(r, c+1, i+1)
		board[r][c] = old
		return ok
	}
	for r := range board {
		for c := range board[r] {
			if dfs(r, c, 0) {
				return true
			}
		}
	}
	return false
}

