func partition(s string) [][]string {
	n := len(s)
	pal := make([][]bool, n)
	for i := range pal {
		pal[i] = make([]bool, n)
	}
	for l := n - 1; l >= 0; l-- {
		for r := l; r < n; r++ {
			pal[l][r] = s[l] == s[r] && (r-l < 2 || pal[l+1][r-1])
		}
	}
	ans := [][]string{}
	path := []string{}
	var dfs func(int)
	dfs = func(start int) {
		if start == n {
			ans = append(ans, append([]string{}, path...))
			return
		}
		for end := start; end < n; end++ {
			if pal[start][end] {
				path = append(path, s[start:end+1])
				dfs(end + 1)
				path = path[:len(path)-1]
			}
		}
	}
	dfs(0)
	return ans
}

