import "strings"

func restoreIpAddresses(s string) []string {
	ans := []string{}
	parts := []string{}
	var dfs func(int)
	dfs = func(start int) {
		left := 4 - len(parts)
		if len(s)-start < left || len(s)-start > left*3 {
			return
		}
		if left == 0 {
			ans = append(ans, strings.Join(parts, "."))
			return
		}
		v := 0
		for end := start; end < len(s) && end < start+3; end++ {
			if end > start && s[start] == '0' {
				break
			}
			v = v*10 + int(s[end]-'0')
			if v > 255 {
				break
			}
			parts = append(parts, s[start:end+1])
			dfs(end + 1)
			parts = parts[:len(parts)-1]
		}
	}
	dfs(0)
	return ans
}

