func longestCommonSubsequence(a, b string) int {
	if len(a) < len(b) {
		a, b = b, a
	}
	dp := make([]int, len(b)+1)
	for i := range a {
		diag := 0
		for j := 1; j <= len(b); j++ {
			old := dp[j]
			if a[i] == b[j-1] {
				dp[j] = diag + 1
			} else {
				dp[j] = max(dp[j], dp[j-1])
			}
			diag = old
		}
	}
	return dp[len(b)]
}

