func minDistance(a, b string) int {
	if len(a) < len(b) {
		a, b = b, a
	}
	dp := make([]int, len(b)+1)
	for j := range dp {
		dp[j] = j
	}
	for i := 1; i <= len(a); i++ {
		diag := dp[0]
		dp[0] = i
		for j := 1; j <= len(b); j++ {
			old := dp[j]
			if a[i-1] == b[j-1] {
				dp[j] = diag
			} else {
				dp[j] = 1 + min(diag, min(dp[j], dp[j-1]))
			}
			diag = old
		}
	}
	return dp[len(b)]
}

