import "strings"

func decodeString(s string) string {
	counts := []int{}
	frames := []string{}
	cur := ""
	num := 0
	for i := range s {
		c := s[i]
		if c >= '0' && c <= '9' {
			num = num*10 + int(c-'0')
		} else if c == '[' {
			counts = append(counts, num)
			frames = append(frames, cur)
			cur = ""
			num = 0
		} else if c == ']' {
			j := len(counts) - 1
			cur = frames[j] + strings.Repeat(cur, counts[j])
			counts = counts[:j]
			frames = frames[:j]
		} else {
			cur += string(c)
		}
	}
	return cur
}

