import "container/heap"

type state struct{ v, d int }
type priority []state

func (h priority) Len() int           { return len(h) }
func (h priority) Less(i, j int) bool { return h[i].d < h[j].d }
func (h priority) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *priority) Push(x any)        { *h = append(*h, x.(state)) }
func (h *priority) Pop() any          { a := *h; x := a[len(a)-1]; *h = a[:len(a)-1]; return x }
func kthSmallest(matrix [][]int, k int) int {
	n := len(matrix[0])
	h := &priority{}
	for r, row := range matrix {
		*h = append(*h, state{r * n, row[0]})
	}
	heap.Init(h)
	ans := 0
	for i := 0; i < k; i++ {
		s := heap.Pop(h).(state)
		ans = s.d
		r, c := s.v/n, s.v%n
		if c+1 < n {
			heap.Push(h, state{r*n + c + 1, matrix[r][c+1]})
		}
	}
	return ans
}

