func canCompleteCircuit(gas, cost []int) int {
	total, tank, start := 0, 0, 0
	for i, x := range gas {
		d := x - cost[i]
		total += d
		tank += d
		if tank < 0 {
			start = i + 1
			tank = 0
		}
	}
	if total < 0 {
		return -1
	}
	return start
}

