type trieNode struct {
	children [26]*trieNode
	word     string
}

func findWords(board [][]byte, words []string) []string {
	root := &trieNode{}
	for _, w := range words {
		t := root
		for i := range w {
			j := w[i] - 'a'
			if t.children[j] == nil {
				t.children[j] = &trieNode{}
			}
			t = t.children[j]
		}
		t.word = w
	}
	ans := []string{}
	var dfs func(int, int, *trieNode)
	dfs = func(r, c int, t *trieNode) {
		if r < 0 || r >= len(board) || c < 0 || c >= len(board[0]) || board[r][c] == 0 {
			return
		}
		ch := board[r][c]
		t = t.children[ch-'a']
		if t == nil {
			return
		}
		if t.word != "" {
			ans = append(ans, t.word)
			t.word = ""
		}
		board[r][c] = 0
		dfs(r-1, c, t)
		dfs(r+1, c, t)
		dfs(r, c-1, t)
		dfs(r, c+1, t)
		board[r][c] = ch
	}
	for r := range board {
		for c := range board[r] {
			dfs(r, c, root)
		}
	}
	return ans
}

