	dummy := &ListNode{Next: head}
	prev := dummy
	for cur := head; cur != nil; {
		last := cur
		for last.Next != nil && last.Next.Val == cur.Val {
			last = last.Next
		}
		if last != cur {
			prev.Next = last.Next
		} else {
