import "container/heap"

type pairEntry struct {
	i, j int
	s    int64
}
type pairHeap []pairEntry

func (h pairHeap) Len() int { return len(h) }
func (h pairHeap) Less(i, j int) bool {
	if h[i].s != h[j].s {
		return h[i].s < h[j].s
	}
	if h[i].i != h[j].i {
		return h[i].i < h[j].i
	}
	return h[i].j < h[j].j
}
func (h pairHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }
func (h *pairHeap) Push(v any)   { *h = append(*h, v.(pairEntry)) }
func (h *pairHeap) Pop() any     { a := *h; x := a[len(a)-1]; *h = a[:len(a)-1]; return x }
func kSmallestPairs(a, b []int, k int) [][]int {
	out := [][]int{}
	if len(a) == 0 || len(b) == 0 || k <= 0 {
		return out
	}
	h := &pairHeap{}
	for i := 0; i < len(a) && i < k; i++ {
		heap.Push(h, pairEntry{i, 0, int64(a[i]) + int64(b[0])})
	}
	for h.Len() > 0 && len(out) < k {
		x := heap.Pop(h).(pairEntry)
		out = append(out, []int{a[x.i], b[x.j]})
		if x.j+1 < len(b) {
			j := x.j + 1
			heap.Push(h, pairEntry{x.i, j, int64(a[x.i]) + int64(b[j])})
		}
	}
	return out
}

