import "sort"

func diagonalSort(mat [][]int) [][]int {
	if len(mat) == 0 || len(mat[0]) == 0 {
		return mat
	}
	m, n := len(mat), len(mat[0])
	line := func(r, c int) {
		a := []int{}
		for i, j := r, c; i < m && j < n; i, j = i+1, j+1 {
			a = append(a, mat[i][j])
		}
		sort.Ints(a)
		for i, j, k := r, c, 0; i < m && j < n; i, j, k = i+1, j+1, k+1 {
			mat[i][j] = a[k]
		}
	}
	for r := 0; r < m; r++ {
		line(r, 0)
	}
	for c := 1; c < n; c++ {
		line(0, c)
	}
	return mat
}

