func shiftGrid(grid [][]int, k int) [][]int {
	if len(grid) == 0 || len(grid[0]) == 0 {
		return grid
	}
	m, n := len(grid), len(grid[0])
	out := make([][]int, m)
	for r := range out {
		out[r] = make([]int, n)
	}
	k %= m * n
	for r := 0; r < m; r++ {
		for c := 0; c < n; c++ {
			p := (r*n + c + k) % (m * n)
			out[p/n][p%n] = grid[r][c]
		}
	}
	return out
}

