func matrixBlockSum(mat [][]int, k int) [][]int {
	if len(mat) == 0 {
		return [][]int{}
	}
	m, n := len(mat), len(mat[0])
	p := make([][]int, m+1)
	for r := range p {
		p[r] = make([]int, n+1)
	}
	for r := 0; r < m; r++ {
		for c := 0; c < n; c++ {
			p[r+1][c+1] = mat[r][c] + p[r][c+1] + p[r+1][c] - p[r][c]
		}
	}
	out := make([][]int, m)
	for r := 0; r < m; r++ {
		out[r] = make([]int, n)
		for c := 0; c < n; c++ {
			a, b := r-k, r+k+1
			l, h := c-k, c+k+1
			if a < 0 {
				a = 0
			}
			if b > m {
				b = m
			}
			if l < 0 {
				l = 0
			}
			if h > n {
				h = n
			}
			out[r][c] = p[b][h] - p[a][h] - p[b][l] + p[a][l]
		}
	}
	return out
}

