func subarraysDivByK(nums []int, k int) int {
	freq := make([]int, k)
	freq[0] = 1
	rem, answer := 0, 0
	for _, x := range nums {
		rem = (rem + x) % k
		if rem < 0 {
			rem += k
		}
		answer += freq[rem]
		freq[rem]++
	}
	return answer
}

