func minOperations(nums []int, x int) int {
	target := -x
	for _, v := range nums {
		target += v
	}
	if target < 0 {
		return -1
	}
	left, sum, best := 0, 0, -1
	if target == 0 {
		best = 0
	}
	for right, v := range nums {
		sum += v
		for left <= right && sum > target {
			sum -= nums[left]
			left++
		}
		if sum == target && right-left+1 > best {
			best = right - left + 1
		}
	}
	if best < 0 {
		return -1
	}
	return len(nums) - best
}

