func longestOnes(nums []int, k int) int {
	left, zero, best := 0, 0, 0
	for right, x := range nums {
		if x == 0 {
			zero++
		}
		for zero > k {
			if nums[left] == 0 {
				zero--
			}
			left++
		}
		if right-left+1 > best {
			best = right - left + 1
		}
	}
	return best
}

