func characterReplacement(s string, k int) int {
	var count [26]int
	left, best := 0, 0
	maximum := func() int {
		m := 0
		for _, v := range count {
			if v > m {
				m = v
			}
		}
		return m
	}
	for right := 0; right < len(s); right++ {
		count[s[right]-'A']++
		for right-left+1-maximum() > k {
			count[s[left]-'A']--
			left++
		}
		if right-left+1 > best {
			best = right - left + 1
		}
	}
	return best
}

