func containsNearbyAlmostDuplicate(nums []int, indexDiff int, valueDiff int) bool {
	if indexDiff <= 0 || valueDiff < 0 {
		return false
	}
	w := int64(valueDiff) + 1
	bucket := func(x int64) int64 {
		if x < 0 {
			return (x+1)/w - 1
		}
		return x / w
	}
	slots := map[int64]int64{}
	for i, v := range nums {
		x := int64(v)
		id := bucket(x)
		if _, ok := slots[id]; ok {
			return true
		}
		if y, ok := slots[id-1]; ok && x-y <= int64(valueDiff) {
			return true
		}
		if y, ok := slots[id+1]; ok && y-x <= int64(valueDiff) {
			return true
		}
		slots[id] = x
		if i >= indexDiff {
			delete(slots, bucket(int64(nums[i-indexDiff])))
		}
	}
	return false
}

