func longestSubstring(s string, k int) int {
	if k <= 1 {
		return len(s)
	}
	best := 0
	for limit := 1; limit <= 26; limit++ {
		var count [26]int
		left, distinct, enough := 0, 0, 0
		for right := 0; right < len(s); right++ {
			x := s[right] - 'a'
			if count[x] == 0 {
				distinct++
			}
			count[x]++
			if count[x] == k {
				enough++
			}
			for distinct > limit {
				y := s[left] - 'a'
				if count[y] == k {
					enough--
				}
				count[y]--
				if count[y] == 0 {
					distinct--
				}
				left++
			}
			if distinct == limit && enough == limit && right-left+1 > best {
				best = right - left + 1
			}
		}
	}
	return best
}

