type calendarNode struct {
	left, right  *calendarNode
	add, maximum int
}

func nodeMaximum(n *calendarNode) int {
	if n == nil {
		return 0
	}
	return n.maximum
}
func calendarAdd(n **calendarNode, lo, hi, a, b int) {
	if b <= lo || hi <= a {
		return
	}
	if *n == nil {
		*n = &calendarNode{}
	}
	x := *n
	if a <= lo && hi <= b {
		x.add++
		x.maximum++
		return
	}
	mid := lo + (hi-lo)/2
	calendarAdd(&x.left, lo, mid, a, b)
	calendarAdd(&x.right, mid, hi, a, b)
	x.maximum = x.add + max(nodeMaximum(x.left), nodeMaximum(x.right))
}
func calendarQuery(n *calendarNode, lo, hi, a, b int) int {
	if n == nil || b <= lo || hi <= a {
		return 0
	}
	if a <= lo && hi <= b {
		return n.maximum
	}
	mid := lo + (hi-lo)/2
	return n.add + max(calendarQuery(n.left, lo, mid, a, b), calendarQuery(n.right, mid, hi, a, b))
}

type MyCalendar struct{ root *calendarNode }

func Constructor() MyCalendar { return MyCalendar{} }
func (c *MyCalendar) Book(start, end int) bool {
	if start >= end || start < 0 || end > 1000000000 {
		return false
	}
	if calendarQuery(c.root, 0, 1000000000, start, end) >= 1 {
		return false
	}
	calendarAdd(&c.root, 0, 1000000000, start, end)
	return true
}

