import "sort"

type heightTree struct {
	mx, tag []int
	pending []bool
}

func (t *heightTree) apply(i, h int) { t.mx[i] = h; t.tag[i] = h; t.pending[i] = true }
func (t *heightTree) push(i int) {
	if t.pending[i] {
		t.apply(i*2, t.tag[i])
		t.apply(i*2+1, t.tag[i])
		t.pending[i] = false
	}
}
func (t *heightTree) query(i, l, r, a, b int) int {
	if b <= l || r <= a {
		return 0
	}
	if a <= l && r <= b {
		return t.mx[i]
	}
	t.push(i)
	m := l + (r-l)/2
	return max(t.query(i*2, l, m, a, b), t.query(i*2+1, m, r, a, b))
}
func (t *heightTree) set(i, l, r, a, b, h int) {
	if b <= l || r <= a {
		return
	}
	if a <= l && r <= b {
		t.apply(i, h)
		return
	}
	t.push(i)
	m := l + (r-l)/2
	t.set(i*2, l, m, a, b, h)
	t.set(i*2+1, m, r, a, b, h)
	t.mx[i] = max(t.mx[i*2], t.mx[i*2+1])
}
func fallingSquares(positions [][]int) []int {
	out := []int{}
	if len(positions) == 0 {
		return out
	}
	coords := []int{}
	for _, p := range positions {
		coords = append(coords, p[0], p[0]+p[1])
	}
	sort.Ints(coords)
	w := 0
	for _, x := range coords {
		if w == 0 || coords[w-1] != x {
			coords[w] = x
			w++
		}
	}
	coords = coords[:w]
	n := len(coords) - 1
	t := heightTree{mx: make([]int, 4*n+4), tag: make([]int, 4*n+4), pending: make([]bool, 4*n+4)}
	for _, p := range positions {
		l := sort.SearchInts(coords, p[0])
		r := sort.SearchInts(coords, p[0]+p[1])
		h := t.query(1, 0, n, l, r) + p[1]
		t.set(1, 0, n, l, r, h)
		out = append(out, t.mx[1])
	}
	return out
}

