func shortestSubarray(nums []int, k int) int {
	p := make([]int64, len(nums)+1)
	for i, x := range nums {
		p[i+1] = p[i] + int64(x)
	}
	q := []int{}
	head, best := 0, len(nums)+1
	for i, s := range p {
		for head < len(q) && s-p[q[head]] >= int64(k) {
			best = min(best, i-q[head])
			head++
		}
		for len(q) > head && s <= p[q[len(q)-1]] {
			q = q[:len(q)-1]
		}
		q = append(q, i)
	}
	if best > len(nums) {
		return -1
	}
	return best
}

maximum-sum-circular-subarray.go:
func maxSubarraySumCircular(nums []int) int {
	total, hi, lo, best, worst := nums[0], nums[0], nums[0], nums[0], nums[0]
	for _, x := range nums[1:] {
		hi = max(x, hi+x)
		lo = min(x, lo+x)
		best = max(best, hi)
		worst = min(worst, lo)
		total += x
	}
	if best < 0 {
		return best
	}
	return max(best, total-worst)
}

