func maxResult(nums []int, k int) int {
	d := make([]int, len(nums))
	d[0] = nums[0]
	q := []int{0}
	head := 0
	for i := 1; i < len(nums); i++ {
		for head < len(q) && q[head] < i-k {
			head++
		}
		d[i] = nums[i] + d[q[head]]
		for len(q) > head && d[q[len(q)-1]] <= d[i] {
			q = q[:len(q)-1]
		}
		q = append(q, i)
	}
	return d[len(nums)-1]
}

