func constrainedSubsetSum(nums []int, k int) int {
	d := make([]int, len(nums))
	q := []int{}
	head := 0
	best := nums[0]
	for i, x := range nums {
		for head < len(q) && q[head] < i-k {
			head++
		}
		d[i] = x
		if head < len(q) {
			d[i] += d[q[head]]
		}
		best = max(best, d[i])
		if d[i] > 0 {
			for len(q) > head && d[q[len(q)-1]] <= d[i] {
				q = q[:len(q)-1]
			}
			q = append(q, i)
		}
	}
	return best
}

