func matrixReshape(mat [][]int, r, c int) [][]int {
	if len(mat) == 0 {
		return mat
	}
	m, n := len(mat), len(mat[0])
	if m*n != r*c {
		return mat
	}
	out := make([][]int, r)
	for i := range out {
		out[i] = make([]int, c)
	}
	for p := 0; p < m*n; p++ {
		out[p/c][p%c] = mat[p/n][p%n]
	}
	return out
}

