import "sort"

func numMatchingSubseq(s string, words []string) int {
	var pos [26][]int
	for i := 0; i < len(s); i++ {
		x := s[i] - 'a'
		pos[x] = append(pos[x], i)
	}
	answer := 0
	for _, w := range words {
		last, ok := -1, true
		for i := 0; i < len(w); i++ {
			a := pos[w[i]-'a']
			j := sort.Search(len(a), func(j int) bool { return a[j] > last })
			if j == len(a) {
				ok = false
				break
			}
			last = a[j]
		}
		if ok {
			answer++
		}
	}
	return answer
}

