func findClosestElements(arr []int, k, x int) []int {
	lo, hi := 0, len(arr)-k
	for lo < hi {
		mid := lo + (hi-lo)/2
		if int64(x)-int64(arr[mid]) > int64(arr[mid+k])-int64(x) {
			lo = mid + 1
		} else {
			hi = mid
		}
	}
	return append([]int(nil), arr[lo:lo+k]...)
}

