func reorderList(head *ListNode) {
	if head == nil || head.Next == nil {
		return
	}
	slow, fast := head, head
	for fast.Next != nil && fast.Next.Next != nil {
		slow = slow.Next
		fast = fast.Next.Next
	}
	cur := slow.Next
	slow.Next = nil
	var rev *ListNode
	for cur != nil {
		next := cur.Next
		cur.Next = rev
		rev = cur
		cur = next
	}
	a, b := head, rev
	for b != nil {
		nextA, nextB := a.Next, b.Next
		a.Next = b
		b.Next = nextA
		a, b = nextA, nextB
	}
}

