import "strconv"

func evalRPN(tokens []string) int {
	stack := []int{}
	for _, s := range tokens {
		if x, err := strconv.Atoi(s); err == nil {
			stack = append(stack, x)
			continue
		}
		n := len(stack)
		a, b := stack[n-2], stack[n-1]
		stack = stack[:n-2]
		value := 0
		switch s {
		case "+":
			value = a + b
		case "-":
			value = a - b
		case "*":
			value = a * b
		case "/":
			value = a / b
		default:
			panic("invalid operator")
		}
		stack = append(stack, value)
	}
	return stack[0]
}

