import "container/list"

type MyStack struct{ q *list.List }

func Constructor() MyStack { return MyStack{q: list.New()} }
func (s *MyStack) Push(x int) {
	n := s.q.Len()
	s.q.PushBack(x)
	for i := 0; i < n; i++ {
		e := s.q.Front()
		v := e.Value.(int)
		s.q.Remove(e)
		s.q.PushBack(v)
	}
}
func (s *MyStack) Pop() int {
	e := s.q.Front()
	if e == nil {
		return -1
	}
	s.q.Remove(e)
	return e.Value.(int)
}
func (s *MyStack) Top() int {
	if s.q.Len() == 0 {
		return -1
	}
	return s.q.Front().Value.(int)
}
func (s *MyStack) Empty() bool { return s.q.Len() == 0 }

