import "strings"

func lengthLongestPath(input string) int {
	prefix := []int{0}
	best := 0
	for _, line := range strings.Split(input, "\n") {
		d := 0
		for d < len(line) && line[d] == '\t' {
			d++
		}
		name := line[d:]
		prefix = prefix[:d+1]
		length := prefix[d] + len(name)
		if strings.Contains(name, ".") {
			best = max(best, length)
		} else {
			prefix = append(prefix, length+1)
		}
	}
	return best
}

maximum-frequency-stack.go:
type FreqStack struct {
	freq    map[int]int
	groups  map[int][]int
	highest int
}

func Constructor() FreqStack { return FreqStack{freq: map[int]int{}, groups: map[int][]int{}} }
func (s *FreqStack) Push(val int) {
	s.freq[val]++
	f := s.freq[val]
	s.groups[f] = append(s.groups[f], val)
	s.highest = max(s.highest, f)
}
func (s *FreqStack) Pop() int {
	if s.highest == 0 {
		return -1
	}
	a := s.groups[s.highest]
	v := a[len(a)-1]
	a = a[:len(a)-1]
	s.freq[v]--
	if s.freq[v] == 0 {
		delete(s.freq, v)
	}
	if len(a) == 0 {
		delete(s.groups, s.highest)
		s.highest--
	} else {
		s.groups[s.highest] = a
	}
	return v
}

