func minAddToMakeValid(s string) int {
	open, added := 0, 0
	for _, c := range s {
		if c == '(' {
			open++
		} else if open > 0 {
			open--
		} else {
			added++
		}
	}
	return added + open
}

minimum-insertions-to-balance-a-parenthe.go:
func minInsertions(s string) int {
	need, added := 0, 0
	for _, c := range s {
		if c == '(' {
			if need%2 == 1 {
				added++
				need--
			}
			need += 2
		} else {
			need--
			if need < 0 {
				added++
				need = 1
			}
		}
	}
	return added + need
}

