type MyCircularDeque struct {
	data       []int
	head, size int
}

func Constructor(k int) MyCircularDeque { return MyCircularDeque{data: make([]int, k)} }
func (q *MyCircularDeque) InsertFront(value int) bool {
	if q.IsFull() {
		return false
	}
	q.head = (q.head - 1 + len(q.data)) % len(q.data)
	q.data[q.head] = value
	q.size++
	return true
}
func (q *MyCircularDeque) InsertLast(value int) bool {
	if q.IsFull() {
		return false
	}
	q.data[(q.head+q.size)%len(q.data)] = value
	q.size++
	return true
}
func (q *MyCircularDeque) DeleteFront() bool {
	if q.IsEmpty() {
		return false
	}
	q.head = (q.head + 1) % len(q.data)
	q.size--
	return true
}
func (q *MyCircularDeque) DeleteLast() bool {
	if q.IsEmpty() {
		return false
	}
	q.size--
	return true
}
func (q *MyCircularDeque) GetFront() int {
	if q.IsEmpty() {
		return -1
	}
	return q.data[q.head]
}
func (q *MyCircularDeque) GetRear() int {
	if q.IsEmpty() {
		return -1
	}
	return q.data[(q.head+q.size-1)%len(q.data)]
}
func (q *MyCircularDeque) IsEmpty() bool { return q.size == 0 }
func (q *MyCircularDeque) IsFull() bool  { return q.size == len(q.data) }

