import "container/list"

type FrontMiddleBackQueue struct{ a, b *list.List }

func Constructor() FrontMiddleBackQueue { return FrontMiddleBackQueue{a: list.New(), b: list.New()} }
func (q *FrontMiddleBackQueue) balance() {
	if q.a.Len() > q.b.Len()+1 {
		e := q.a.Back()
		q.a.Remove(e)
		q.b.PushFront(e.Value)
	} else if q.a.Len() < q.b.Len() {
		e := q.b.Front()
		q.b.Remove(e)
		q.a.PushBack(e.Value)
	}
}
func (q *FrontMiddleBackQueue) PushFront(v int) { q.a.PushFront(v); q.balance() }
func (q *FrontMiddleBackQueue) PushMiddle(v int) {
	if q.a.Len() > q.b.Len() {
		e := q.a.Back()
		q.a.Remove(e)
		q.b.PushFront(e.Value)
	}
	q.a.PushBack(v)
}
func (q *FrontMiddleBackQueue) PushBack(v int) { q.b.PushBack(v); q.balance() }
func (q *FrontMiddleBackQueue) PopFront() int {
	if q.a.Len() == 0 {
		return -1
	}
	e := q.a.Front()
	q.a.Remove(e)
	q.balance()
	return e.Value.(int)
}
func (q *FrontMiddleBackQueue) PopMiddle() int {
	if q.a.Len() == 0 {
		return -1
	}
	e := q.a.Back()
	q.a.Remove(e)
	q.balance()
	return e.Value.(int)
}
func (q *FrontMiddleBackQueue) PopBack() int {
	var e *list.Element
	if q.b.Len() > 0 {
		e = q.b.Back()
		q.b.Remove(e)
	} else if q.a.Len() > 0 {
		e = q.a.Back()
		q.a.Remove(e)
	} else {
		return -1
	}
	q.balance()
	return e.Value.(int)
}

