func removeKdigits(num string, k int) string {
	stack := []byte{}
	for i := 0; i < len(num); i++ {
		c := num[i]
		for k > 0 && len(stack) > 0 && stack[len(stack)-1] > c {
			stack = stack[:len(stack)-1]
			k--
		}
		stack = append(stack, c)
	}
	stack = stack[:len(stack)-k]
	answer := strings.TrimLeft(string(stack), "0")
	if answer == "" {
		return "0"
	}
	return answer
}

