func removeDuplicateLetters(s string) string {
	var remaining [26]int
	var used [26]bool
	for i := 0; i < len(s); i++ {
		remaining[s[i]-'a']++
	}
	stack := []byte{}
	for i := 0; i < len(s); i++ {
		c := s[i]
		remaining[c-'a']--
		if used[c-'a'] {
			continue
		}
		for len(stack) > 0 {
			top := stack[len(stack)-1]
			if top <= c || remaining[top-'a'] == 0 {
				break
			}
			used[top-'a'] = false
			stack = stack[:len(stack)-1]
		}
		stack = append(stack, c)
		used[c-'a'] = true
	}
	return string(stack)
}

