import "sort"

type fleetCar struct{ position, speed int }

func carFleet(target int, position, speed []int) int {
	cars := make([]fleetCar, len(position))
	for i, p := range position {
		cars[i] = fleetCar{p, speed[i]}
	}
	sort.Slice(cars, func(i, j int) bool { return cars[i].position > cars[j].position })
	count := 0
	var distance, denominator int64
	for _, c := range cars {
		d, s := int64(target-c.position), int64(c.speed)
		if count == 0 || d*denominator > distance*s {
			count++
			distance, denominator = d, s
		}
	}
	return count
}

