func findUnsortedSubarray(nums []int) int {
	if len(nums) == 0 {
		return 0
	}
	largest, smallest := nums[0], nums[len(nums)-1]
	left, right := 0, -1
	for i := range nums {
		largest = max(largest, nums[i])
		if nums[i] < largest {
			right = i
		}
		j := len(nums) - 1 - i
		smallest = min(smallest, nums[j])
		if nums[j] > smallest {
			left = j
		}
	}
	if right < 0 {
		return 0
	}
	return right - left + 1
}

