func flipMatchVoyage(root *TreeNode, voyage []int) []int {
	flips := []int{}
	i := 0
	var visit func(*TreeNode) bool
	visit = func(n *TreeNode) bool {
		if n == nil {
			return true
		}
		if i >= len(voyage) || voyage[i] != n.Val {
			return false
		}
		i++
		if n.Left != nil && i < len(voyage) && voyage[i] != n.Left.Val {
			flips = append(flips, n.Val)
			return visit(n.Right) && visit(n.Left)
		}
		return visit(n.Left) && visit(n.Right)
	}
	if !visit(root) || i != len(voyage) {
		return []int{-1}
	}
	return flips
}

