import "sort"

type verticalEntry struct{ column, row, value int }

func verticalTraversal(root *TreeNode) [][]int {
	nodes := []verticalEntry{}
	var dfs func(*TreeNode, int, int)
	dfs = func(n *TreeNode, row, col int) {
		if n == nil {
			return
		}
		nodes = append(nodes, verticalEntry{col, row, n.Val})
		dfs(n.Left, row+1, col-1)
		dfs(n.Right, row+1, col+1)
	}
	dfs(root, 0, 0)
	sort.Slice(nodes, func(i, j int) bool {
		a, b := nodes[i], nodes[j]
		if a.column != b.column {
			return a.column < b.column
		}
		if a.row != b.row {
			return a.row < b.row
		}
		return a.value < b.value
	})
	out := [][]int{}
	for i, x := range nodes {
		if i == 0 || x.column != nodes[i-1].column {
			out = append(out, []int{})
		}
		last := len(out) - 1
		out[last] = append(out[last], x.value)
	}
	return out
}

