type cousinEntry struct{ node, parent *TreeNode }

func isCousins(root *TreeNode, x, y int) bool {
	if root == nil {
		return false
	}
	q := []cousinEntry{{root, nil}}
	for len(q) > 0 {
		count := len(q)
		var px, py *TreeNode
		foundX, foundY := false, false
		for _, e := range q[:count] {
			n := e.node
			if n.Val == x {
				foundX = true
				px = e.parent
			}
			if n.Val == y {
				foundY = true
				py = e.parent
			}
			if n.Left != nil {
				q = append(q, cousinEntry{n.Left, n})
			}
			if n.Right != nil {
				q = append(q, cousinEntry{n.Right, n})
			}
		}
		if foundX || foundY {
			return foundX && foundY && px != py
		}
		q = q[count:]
	}
	return false
}

