func lexicalOrder(n int) []int {
	out := make([]int, 0, n)
	var visit func(int)
	visit = func(v int) {
		if v > n {
			return
		}
		out = append(out, v)
		for d := 0; d < 10; d++ {
			next := v*10 + d
			if next > n {
				break
			}
			visit(next)
