func pathInZigZagTree(label int) []int {
	lo := 1
	for lo <= label/2 {
		lo *= 2
	}
	path := []int{}
	for label > 0 {
		path = append(path, label)
		label = (lo + 2*lo - 1 - label) / 2
		lo /= 2
	}
	for i, j := 0, len(path)-1; i < j; i, j = i+1, j-1 {
		path[i], path[j] = path[j], path[i]
	}
	return path
}

