import "strings"

func getDirections(root *TreeNode, startValue, destValue int) string {
	var find func(*TreeNode, int, *[]byte) bool
	find = func(n *TreeNode, v int, path *[]byte) bool {
		if n == nil {
			return false
		}
		if n.Val == v {
			return true
		}
		*path = append(*path, 'L')
		if find(n.Left, v, path) {
			return true
		}
		*path = (*path)[:len(*path)-1]
		*path = append(*path, 'R')
		if find(n.Right, v, path) {
			return true
		}
		*path = (*path)[:len(*path)-1]
		return false
	}
	a, b := []byte{}, []byte{}
	if !find(root, startValue, &a) || !find(root, destValue, &b) {
		return ""
	}
	i := 0
	for i < len(a) && i < len(b) && a[i] == b[i] {
		i++
	}
	return strings.Repeat("U", len(a)-i) + string(b[i:])
}

