func buildTree(inorder, postorder []int) *TreeNode {
	pos := map[int]int{}
	for i, v := range inorder {
		pos[v] = i
	}
	at := len(postorder) - 1
	var build func(int, int) *TreeNode
	build = func(lo, hi int) *TreeNode {
		if lo > hi {
			return nil
		}
		v := postorder[at]
		at--
		mid := pos[v]
		n := &TreeNode{Val: v}
		n.Right = build(mid+1, hi)
		n.Left = build(lo, mid-1)
		return n
	}
	return build(0, len(inorder)-1)
}

