func constructFromPrePost(preorder, postorder []int) *TreeNode {
	pos := map[int]int{}
	for i, v := range postorder {
		pos[v] = i
	}
	var build func(int, int, int) *TreeNode
	build = func(a, b, size int) *TreeNode {
		if size == 0 {
			return nil
		}
		n := &TreeNode{Val: preorder[a]}
		if size == 1 {
			return n
		}
		leftSize := pos[preorder[a+1]] - b + 1
		n.Left = build(a+1, b, leftSize)
		n.Right = build(a+1+leftSize, b+leftSize, size-1-leftSize)
		return n
	}
	return build(0, 0, len(preorder))
}

