func allPossibleFBT(n int) []*TreeNode {
	memo := map[int][]*TreeNode{}
	var shapes func(int) []*TreeNode
	shapes = func(size int) []*TreeNode {
		if size%2 == 0 {
			return []*TreeNode{}
		}
		if v, ok := memo[size]; ok {
			return v
		}
		out := []*TreeNode{}
		if size == 1 {
			out = append(out, &TreeNode{})
		} else {
			for left := 1; left < size; left += 2 {
				for _, a := range shapes(left) {
					for _, b := range shapes(size - 1 - left) {
						out = append(out, &TreeNode{Left: a, Right: b})
					}
				}
			}
		}
		memo[size] = out
		return out
	}
	var clone func(*TreeNode) *TreeNode
	clone = func(p *TreeNode) *TreeNode {
		if p == nil {
			return nil
		}
		return &TreeNode{Val: p.Val, Left: clone(p.Left), Right: clone(p.Right)}
	}
	out := []*TreeNode{}
	for _, p := range shapes(n) {
		out = append(out, clone(p))
	}
	return out
}

