func delNodes(root *TreeNode, to_delete []int) []*TreeNode {
	deleted := map[int]bool{}
	for _, v := range to_delete {
		deleted[v] = true
	}
	forest := []*TreeNode{}
	var visit func(*TreeNode, bool) *TreeNode
	visit = func(p *TreeNode, isRoot bool) *TreeNode {
		if p == nil {
			return nil
		}
		remove := deleted[p.Val]
		if isRoot && !remove {
			forest = append(forest, p)
		}
		p.Left = visit(p.Left, remove)
		p.Right = visit(p.Right, remove)
		if remove {
			return nil
		}
		return p
	}
	visit(root, true)
	return forest
}

