	sum = func(p *TreeNode) int {
		if p == nil {
			return 0
		}
		left, right := sum(p.Left), sum(p.Right)
		delta := left - right
		if delta < 0 {
			delta = -delta
		}
		answer += delta
		return left + right + p.Val
	}
	sum(root)
	return answer
}

