	totalSum = func(p *TreeNode) int64 {
		if p == nil {
			return 0
		}
		return int64(p.Val) + totalSum(p.Left) + totalSum(p.Right)
	}
	total := totalSum(root)
	best := int64(0)
	var visit func(*TreeNode) int64
	visit = func(p *TreeNode) int64 {
		if p == nil {
			return 0
		}
		s := int64(p.Val) + visit(p.Left) + visit(p.Right)
		if p != root {
			best = max(best, s*(total-s))
		}
		return s
	}
	visit(root)
	return int(best % 1000000007)
}

