func minTime(n int, edges [][]int, hasApple []bool) int {
	if n == 0 {
		return 0
	}
	g := make([][]int, n)
	for _, e := range edges {
		a, b := e[0], e[1]
		g[a] = append(g[a], b)
		g[b] = append(g[b], a)
	}
	parent := make([]int, n)
	parent[0] = -1
	order := []int{0}
	for i := 0; i < len(order); i++ {
		u := order[i]
		for _, v := range g[u] {
			if v != parent[u] {
				parent[v] = u
				order = append(order, v)
			}
		}
	}
	needed := append([]bool(nil), hasApple...)
	cost := 0
	for i := len(order) - 1; i > 0; i-- {
		u := order[i]
		if needed[u] {
			cost += 2
			needed[parent[u]] = true
		}
	}
	return cost
}

