	visit = func(p *TreeNode) int {
		if p == nil {
			return covered
		}
		left, right := visit(p.Left), visit(p.Right)
		if left == uncovered || right == uncovered {
			count++
			return camera
		}
		if left == camera || right == camera {
			return covered
		}
		return uncovered
	}
	if visit(root) == uncovered {
		count++
	}
	return count
}

