func countHighestScoreNodes(parents []int) int {
	n := len(parents)
	children := make([][]int, n)
	for v := 1; v < n; v++ {
		p := parents[v]
		children[p] = append(children[p], v)
	}
	order := []int{0}
	for i := 0; i < len(order); i++ {
		order = append(order, children[order[i]]...)
	}
	size := make([]int, n)
	best := int64(0)
	count := 0
	for i := len(order) - 1; i >= 0; i-- {
		u := order[i]
		size[u] = 1
		score := int64(1)
		for _, v := range children[u] {
			size[u] += size[v]
			score *= int64(size[v])
		}
		if rest := n - size[u]; rest > 0 {
			score *= int64(rest)
		}
		if score > best {
			best = score
			count = 1
		} else if score == best {
			count++
		}
	}
	return count
}

