func maxSumBST(root *TreeNode) int {
	type info struct {
		valid, empty bool
		lo, hi, sum  int
	}
	best := 0
	var visit func(*TreeNode) info
	visit = func(p *TreeNode) info {
		if p == nil {
			return info{valid: true, empty: true}
		}
		a, b := visit(p.Left), visit(p.Right)
		if !a.valid || !b.valid || (!a.empty && a.hi >= p.Val) || (!b.empty && b.lo <= p.Val) {
			return info{}
		}
		r := info{valid: true, lo: p.Val, hi: p.Val, sum: a.sum + b.sum + p.Val}
		if !a.empty {
			r.lo = a.lo
		}
		if !b.empty {
			r.hi = b.hi
		}
		best = max(best, r.sum)
		return r
	}
	visit(root)
	return best
}

