	level := []*TreeNode{root}
	for len(level) > 0 {
		row := make([]int, len(level))
		next := []*TreeNode{}
		for i, p := range level {
			row[i] = p.Val
			if p.Left != nil {
				next = append(next, p.Left)
			}
			if p.Right != nil {
				next = append(next, p.Right)
			}
		}
		out = append(out, row)
		level = next
	}
	for i, j := 0, len(out)-1; i < j; i, j = i+1, j-1 {
		out[i], out[j] = out[j], out[i]
	}
	return out
}

