func connect(root *Node) *Node {
	if root == nil {
		return nil
	}
	root.Next = nil
	for level := root; level != nil; {
		dummy := Node{}
		tail := &dummy
		for p := level; p != nil; p = p.Next {
			if p.Left != nil {
				tail.Next = p.Left
				tail = p.Left
			}
			if p.Right != nil {
				tail.Next = p.Right
				tail = p.Right
			}
		}
		tail.Next = nil
		level = dummy.Next
	}
	return root
}

