func widthOfBinaryTree(root *TreeNode) int {
	if root == nil {
		return 0
	}
	type entry struct {
		node *TreeNode
		pos  uint64
	}
	level := []entry{{root, 0}}
	best := uint64(0)
	for len(level) > 0 {
		base := level[0].pos
		best = max(best, level[len(level)-1].pos-base+1)
		next := []entry{}
		for _, e := range level {
			at := e.pos - base
			if e.node.Left != nil {
				next = append(next, entry{e.node.Left, at * 2})
			}
			if e.node.Right != nil {
				next = append(next, entry{e.node.Right, at*2 + 1})
			}
		}
		level = next
	}
	return int(best)
}

