func isEvenOddTree(root *TreeNode) bool {
	if root == nil {
		return true
	}
	level := []*TreeNode{root}
	depth := 0
	for len(level) > 0 {
		first := true
		previous := 0
		next := []*TreeNode{}
		for _, p := range level {
			v := p.Val
			if depth%2 == 0 {
				if v%2 != 1 || (!first && v <= previous) {
					return false
				}
			} else {
				if v%2 != 0 || (!first && v >= previous) {
					return false
				}
			}
			first = false
			previous = v
			if p.Left != nil {
				next = append(next, p.Left)
			}
			if p.Right != nil {
				next = append(next, p.Right)
			}
		}
		depth++
		level = next
	}
	return true
}

