type CBTInserter struct {
	root       *TreeNode
	candidates []*TreeNode
}

func Constructor(root *TreeNode) CBTInserter {
	c := CBTInserter{root: root}
	queue := []*TreeNode{root}
	for at := 0; at < len(queue); at++ {
		p := queue[at]
		if p.Left == nil || p.Right == nil {
			c.candidates = append(c.candidates, p)
		}
		if p.Left != nil {
			queue = append(queue, p.Left)
		}
		if p.Right != nil {
			queue = append(queue, p.Right)
		}
	}
	return c
}
func (c *CBTInserter) Insert(val int) int {
	p := c.candidates[0]
	child := &TreeNode{Val: val}
	if p.Left == nil {
		p.Left = child
	} else {
		p.Right = child
		c.candidates[0] = nil
		c.candidates = c.candidates[1:]
	}
	c.candidates = append(c.candidates, child)
	return p.Val
}
func (c *CBTInserter) Get_root() *TreeNode { return c.root }

