			if p == nil {
				return
			}
			if p.Left == nil && p.Right == nil {
				out = append(out, p.Val)
				return
			}
			visit(p.Left)
			visit(p.Right)
		}
		visit(root)
		return out
	}
	a, b := collect(root1), collect(root2)
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

