func distanceK(root, target *TreeNode, k int) []int {
	out := []int{}
	if root == nil || target == nil || k < 0 {
		return out
	}
	parent := map[*TreeNode]*TreeNode{root: nil}
	stack := []*TreeNode{root}
	for len(stack) > 0 {
		p := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		for _, child := range []*TreeNode{p.Left, p.Right} {
			if child != nil {
				parent[child] = p
				stack = append(stack, child)
			}
		}
	}
	level := []*TreeNode{target}
	seen := map[*TreeNode]bool{target: true}
	for d := 0; d < k && len(level) > 0; d++ {
		next := []*TreeNode{}
		for _, p := range level {
			for _, v := range []*TreeNode{p.Left, p.Right, parent[p]} {
				if v != nil && !seen[v] {
					seen[v] = true
					next = append(next, v)
				}
			}
		}
		level = next
	}
	for _, p := range level {
		out = append(out, p.Val)
	}
	return out
}

