func recoverTree(root *TreeNode) {
	var prev, first, second *TreeNode
	var visit func(*TreeNode)
	visit = func(p *TreeNode) {
		if p == nil {
			return
		}
		visit(p.Left)
		if prev != nil && prev.Val > p.Val {
			if first == nil {
				first = prev
			}
			second = p
		}
		prev = p
		visit(p.Right)
	}
	visit(root)
	if first != nil {
		first.Val, second.Val = second.Val, first.Val
	}
}

