func findSecondMinimumValue(root *TreeNode) int {
	if root == nil {
		return -1
	}
	minimum := root.Val
	answer := 0
	found := false
	var visit func(*TreeNode)
	visit = func(p *TreeNode) {
		if p == nil {
			return
		}
		if p.Val > minimum {
			if !found || p.Val < answer {
				answer = p.Val
				found = true
			}
			return
		}
		visit(p.Left)
		visit(p.Right)
	}
	visit(root)
	if !found {
		return -1
	}
	return answer
}

