func findMode(root *TreeNode) []int {
	answer := []int{}
	first := true
	previous, count, best := 0, 0, 0
	var visit func(*TreeNode)
	visit = func(p *TreeNode) {
		if p == nil {
			return
		}
		visit(p.Left)
		if !first && p.Val == previous {
			count++
		} else {
			count = 1
		}
		first = false
		previous = p.Val
		if count > best {
			best = count
			answer = answer[:0]
			answer = append(answer, p.Val)
		} else if count == best {
			answer = append(answer, p.Val)
		}
		visit(p.Right)
	}
	visit(root)
	return answer
}

