func bstFromPreorder(preorder []int) *TreeNode {
	at := 0
	var build func(int, bool, int, bool) *TreeNode
	build = func(lo int, hasLo bool, hi int, hasHi bool) *TreeNode {
		if at == len(preorder) {
			return nil
		}
		v := preorder[at]
		if (hasLo && v <= lo) || (hasHi && v >= hi) {
			return nil
		}
		at++
		p := &TreeNode{Val: v}
		p.Left = build(lo, hasLo, v, true)
		p.Right = build(v, true, hi, hasHi)
		return p
	}
	return build(0, false, 0, false)
}

