func balanceBST(root *TreeNode) *TreeNode {
	values := []int{}
	var collect func(*TreeNode)
	collect = func(p *TreeNode) {
		if p == nil {
			return
		}
		collect(p.Left)
		values = append(values, p.Val)
		collect(p.Right)
	}
	collect(root)
	var build func(int, int) *TreeNode
	build = func(lo, hi int) *TreeNode {
		if lo == hi {
			return nil
		}
		mid := lo + (hi-lo)/2
		return &TreeNode{Val: values[mid], Left: build(lo, mid), Right: build(mid+1, hi)}
	}
	return build(0, len(values))
}

