import (
	"strconv"
	"strings"
)

type Codec struct{}

func Constructor() Codec { return Codec{} }
func (c *Codec) serialize(root *TreeNode) string {
	tokens := []string{}
	var visit func(*TreeNode)
	visit = func(p *TreeNode) {
		if p == nil {
			return
		}
		tokens = append(tokens, strconv.Itoa(p.Val))
		visit(p.Left)
		visit(p.Right)
	}
	visit(root)
	return strings.Join(tokens, ",")
}
func (c *Codec) deserialize(data string) *TreeNode {
	if data == "" {
		return nil
	}
	parts := strings.Split(data, ",")
	values := make([]int, len(parts))
	for i, s := range parts {
		v, err := strconv.Atoi(s)
		if err != nil {
			return nil
		}
		values[i] = v
	}
	at := 0
	var build func(int, bool, int, bool) *TreeNode
	build = func(lo int, hasLo bool, hi int, hasHi bool) *TreeNode {
		if at == len(values) {
			return nil
		}
		v := values[at]
		if (hasLo && v <= lo) || (hasHi && v >= hi) {
			return nil
		}
		at++
		p := &TreeNode{Val: v}
		p.Left = build(lo, hasLo, v, true)
		p.Right = build(v, true, hi, hasHi)
		return p
	}
	root := build(0, false, 0, false)
	if at != len(values) {
		return nil
	}
	return root
}

