func sortedListToBST(head *ListNode) *TreeNode {
	n := 0
	for p := head; p != nil; p = p.Next {
		n++
	}
	cursor := head
	var build func(int) *TreeNode
	build = func(size int) *TreeNode {
		if size == 0 {
			return nil
		}
		leftSize := size / 2
		left := build(leftSize)
		p := &TreeNode{Val: cursor.Val, Left: left}
		cursor = cursor.Next
		p.Right = build(size - leftSize - 1)
		return p
	}
	return build(n)
}

