type BSTIterator struct{ stack []*TreeNode }

func Constructor(root *TreeNode) BSTIterator { it := BSTIterator{}; it.pushLeft(root); return it }
func (it *BSTIterator) pushLeft(p *TreeNode) {
	for p != nil {
		it.stack = append(it.stack, p)
		p = p.Left
	}
}
func (it *BSTIterator) Next() int {
	p := it.stack[len(it.stack)-1]
	it.stack = it.stack[:len(it.stack)-1]
	it.pushLeft(p.Right)
	return p.Val
}
func (it *BSTIterator) HasNext() bool { return len(it.stack) > 0 }

