func getAllElements(root1, root2 *TreeNode) []int {
	collect := func(root *TreeNode) []int {
		out := []int{}
		var visit func(*TreeNode)
		visit = func(p *TreeNode) {
			if p == nil {
				return
			}
			visit(p.Left)
			out = append(out, p.Val)
			visit(p.Right)
		}
		visit(root)
		return out
	}
	a, b := collect(root1), collect(root2)
	out := make([]int, 0, len(a)+len(b))
	i, j := 0, 0
	for i < len(a) && j < len(b) {
		if a[i] <= b[j] {
			out = append(out, a[i])
			i++
		} else {
			out = append(out, b[j])
			j++
		}
	}
	out = append(out, a[i:]...)
	out = append(out, b[j:]...)
	return out
}

