import "strings"

func wordPattern(pattern, s string) bool {
	words := strings.Fields(s)
	if len(words) != len(pattern) {
		return false
	}
	forward := map[byte]string{}
	reverse := map[string]byte{}
	for i, w := range words {
		p := pattern[i]
		if old, ok := forward[p]; ok && old != w {
			return false
		}
		if old, ok := reverse[w]; ok && old != p {
			return false
		}
		forward[p] = w
		reverse[w] = p
	}
	return true
}

