import (
	"sort"
	"strings"
)

func frequencySort(s string) string {
	count := map[rune]int{}
	for _, r := range s {
		count[r]++
	}
	chars := make([]rune, 0, len(count))
	for r := range count {
		chars = append(chars, r)
	}
	sort.Slice(chars, func(i, j int) bool {
		a, b := chars[i], chars[j]
		if count[a] != count[b] {
			return count[a] > count[b]
		}
		return a < b
	})
	var out strings.Builder
	for _, r := range chars {
		for i := 0; i < count[r]; i++ {
			out.WriteRune(r)
		}
	}
	return out.String()
}

