func nthSuperUglyNumber(n int, primes []int) int {
	dp := make([]int64, n)
	dp[0] = 1
	index := make([]int, len(primes))
	for i := 1; i < n; i++ {
		next := int64(1<<63 - 1)
		for j, p := range primes {
			next = min(next, int64(p)*dp[index[j]])
		}
		dp[i] = next
		for j, p := range primes {
			if int64(p)*dp[index[j]] == next {
				index[j]++
			}
		}
	}
	return int(dp[n-1])
}

