func (h *wordHeap) Push(x any)   { *h = append(*h, x.(wordItem)) }
func (h *wordHeap) Pop() any     { a := *h; x := a[len(a)-1]; *h = a[:len(a)-1]; return x }
func topKFrequent(words []string, k int) []string {
	freq := map[string]int{}
	for _, w := range words {
		freq[w]++
	}
	h := wordHeap{}
	for w, count := range freq {
		heap.Push(&h, wordItem{w, count})
		if len(h) > k {
			heap.Pop(&h)
		}
	}
	out := make([]string, k)
	for i := k - 1; i >= 0; i-- {
		out[i] = heap.Pop(&h).(wordItem).word
	}
	return out
}

