func advantageCount(nums1, nums2 []int) []int {
	a := append([]int{}, nums1...)
	sort.Ints(a)
	order := make([]int, len(nums2))
	for i := range order {
		order[i] = i
	}
	sort.Slice(order, func(i, j int) bool {
		if nums2[order[i]] != nums2[order[j]] {
			return nums2[order[i]] > nums2[order[j]]
		}
		return order[i] < order[j]
	})
	out := make([]int, len(a))
	lo, hi := 0, len(a)-1
	for _, i := range order {
		if a[hi] > nums2[i] {
			out[i] = a[hi]
			hi--
		} else {
			out[i] = a[lo]
			lo++
		}
	}
	return out
}

