)

type cpuTask struct {
	arrival, duration int64
	index             int
}
type taskHeap []cpuTask

func (h taskHeap) Len() int { return len(h) }
func (h taskHeap) Less(i, j int) bool {
	if h[i].duration != h[j].duration {
		return h[i].duration < h[j].duration
	}
	return h[i].index < h[j].index
}
func (h taskHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }
func (h *taskHeap) Push(x any)   { *h = append(*h, x.(cpuTask)) }
func (h *taskHeap) Pop() any     { a := *h; x := a[len(a)-1]; *h = a[:len(a)-1]; return x }
func getOrder(tasks [][]int) []int {
	ordered := make([]cpuTask, len(tasks))
	for i, t := range tasks {
		ordered[i] = cpuTask{int64(t[0]), int64(t[1]), i}
	}
	sort.Slice(ordered, func(i, j int) bool { return ordered[i].arrival < ordered[j].arrival })
	h := taskHeap{}
	out := []int{}
	now := int64(0)
	at := 0
	for at < len(ordered) || len(h) > 0 {
		if len(h) == 0 && at < len(ordered) && now < ordered[at].arrival {
			now = ordered[at].arrival
		}
		for at < len(ordered) && ordered[at].arrival <= now {
			heap.Push(&h, ordered[at])
			at++
		}
		next := heap.Pop(&h).(cpuTask)
		out = append(out, next.index)
		now += next.duration
	}
	return out
}

