import "math/rand"

type Solution struct {
	cols, total, remaining int
	swaps                  map[int]int
}

func Constructor(m, n int) Solution {
	return Solution{cols: n, total: m * n, remaining: m * n, swaps: map[int]int{}}
}
func (s *Solution) resolve(i int) int {
	if v, ok := s.swaps[i]; ok {
		return v
	}
	return i
}
func (s *Solution) Flip() []int {
	r := rand.Intn(s.remaining)
	chosen := s.resolve(r)
	last := s.resolve(s.remaining - 1)
	s.remaining--
	if r != s.remaining {
		s.swaps[r] = last
	}
	delete(s.swaps, s.remaining)
	return []int{chosen / s.cols, chosen % s.cols}
}
func (s *Solution) Reset() { s.remaining = s.total; clear(s.swaps) }

