func connect(root *Node) *Node {
	if root == nil {
		return nil
	}
	root.Next = nil
	for leftmost := root; leftmost.Left != nil; leftmost = leftmost.Left {
		for p := leftmost; p != nil; p = p.Next {
			p.Left.Next = p.Right
			if p.Next != nil {
				p.Right.Next = p.Next.Left
			} else {
				p.Right.Next = nil
			}
		}
	}
	return root
}

