func constructMaximumBinaryTree(nums []int) *TreeNode {
	stack := []*TreeNode{}
	for _, v := range nums {
		p := &TreeNode{Val: v}
		for len(stack) > 0 && stack[len(stack)-1].Val < v {
			p.Left = stack[len(stack)-1]
			stack = stack[:len(stack)-1]
		}
		if len(stack) > 0 {
			stack[len(stack)-1].Right = p
		}
		stack = append(stack, p)
	}
	if len(stack) == 0 {
		return nil
	}
	return stack[0]
}

serialize-and-deserialize-binary-tree.go:
import (
	"strconv"
	"strings"
)

type Codec struct{}

func Constructor() Codec { return Codec{} }
func (c *Codec) serialize(root *TreeNode) string {
	tokens := []string{}
	var visit func(*TreeNode)
	visit = func(p *TreeNode) {
		if p == nil {
			tokens = append(tokens, "#")
			return
		}
		tokens = append(tokens, strconv.Itoa(p.Val))
		visit(p.Left)
		visit(p.Right)
	}
	visit(root)
	return strings.Join(tokens, ",")
}
func (c *Codec) deserialize(data string) *TreeNode {
	tokens := strings.Split(data, ",")
	at := 0
	valid := true
	var read func() *TreeNode
	read = func() *TreeNode {
		if !valid {
			return nil
		}
		if at == len(tokens) {
			valid = false
			return nil
		}
		token := tokens[at]
		at++
		if token == "#" {
			return nil
		}
		v, err := strconv.Atoi(token)
		if err != nil {
			valid = false
			return nil
		}
		p := &TreeNode{Val: v}
		p.Left = read()
		p.Right = read()
		return p
	}
	root := read()
	if !valid || at != len(tokens) {
		return nil
	}
	return root
}

