func findDuplicateSubtrees(root *TreeNode) []*TreeNode {
	type key struct{ value, left, right int }
	ids := map[key]int{}
	count := map[int]int{}
	out := []*TreeNode{}
	var visit func(*TreeNode) int
	visit = func(p *TreeNode) int {
		if p == nil {
			return 0
		}
		k := key{p.Val, visit(p.Left), visit(p.Right)}
		id, ok := ids[k]
		if !ok {
			id = len(ids) + 1
			ids[k] = id
		}
		count[id]++
		if count[id] == 2 {
			out = append(out, p)
		}
		return id
	}
	visit(root)
	return out
}

