func generateTrees(n int) []*TreeNode {
	if n == 0 {
		return []*TreeNode{}
	}
	type interval struct{ lo, hi int }
	memo := map[interval][]*TreeNode{}
	var build func(int, int) []*TreeNode
	build = func(lo, hi int) []*TreeNode {
		if lo > hi {
			return []*TreeNode{nil}
		}
		key := interval{lo, hi}
		if trees, ok := memo[key]; ok {
			return trees
		}
		out := []*TreeNode{}
		for root := lo; root <= hi; root++ {
			for _, left := range build(lo, root-1) {
				for _, right := range build(root+1, hi) {
					out = append(out, &TreeNode{Val: root, Left: left, Right: right})
				}
			}
		}
		memo[key] = out
		return out
	}
	var clone func(*TreeNode) *TreeNode
	clone = func(p *TreeNode) *TreeNode {
		if p == nil {
			return nil
		}
		return &TreeNode{Val: p.Val, Left: clone(p.Left), Right: clone(p.Right)}
	}
	out := []*TreeNode{}
	for _, p := range build(1, n) {
		out = append(out, clone(p))
	}
	return out
}

