type countNode struct {
	children  [26]*countNode
	pass, end int
}
type Trie struct{ root *countNode }

func Constructor() Trie { return Trie{root: &countNode{}} }
func (t *Trie) find(word string) *countNode {
	p := t.root
	for i := 0; i < len(word); i++ {
		p = p.children[word[i]-'a']
		if p == nil {
			return nil
		}
	}
	return p
}
func (t *Trie) Insert(word string) {
	p := t.root
	p.pass++
	for i := 0; i < len(word); i++ {
		at := word[i] - 'a'
		if p.children[at] == nil {
			p.children[at] = &countNode{}
		}
		p = p.children[at]
		p.pass++
	}
	p.end++
}
func (t *Trie) CountWordsEqualTo(word string) int {
	if p := t.find(word); p != nil {
		return p.end
	}
	return 0
}
func (t *Trie) CountWordsStartingWith(prefix string) int {
	if p := t.find(prefix); p != nil {
		return p.pass
	}
	return 0
}
func (t *Trie) Erase(word string) {
	if t.CountWordsEqualTo(word) == 0 {
		return
	}
	p := t.root
	p.pass--
	for i := 0; i < len(word); i++ {
		at := word[i] - 'a'
		child := p.children[at]
		child.pass--
		if child.pass == 0 {
			p.children[at] = nil
			return
		}
		p = child
	}
	p.end--
}

