func Constructor() MapSum { return MapSum{root: &sumNode{}, values: map[string]int{}} }
func (m *MapSum) Insert(key string, val int) {
	delta := val - m.values[key]
	m.values[key] = val
	p := m.root
	p.total += delta
	for i := 0; i < len(key); i++ {
		at := key[i] - 'a'
		if p.children[at] == nil {
			p.children[at] = &sumNode{}
		}
		p = p.children[at]
		p.total += delta
	}
}
func (m *MapSum) Sum(prefix string) int {
	p := m.root
	for i := 0; i < len(prefix); i++ {
		p = p.children[prefix[i]-'a']
		if p == nil {
			return 0
		}
	}
	return p.total
}

