func validateBinaryTreeNodes(n int, leftChild, rightChild []int) bool {
	indegree := make([]int, n)
	for u := 0; u < n; u++ {
		for _, v := range []int{leftChild[u], rightChild[u]} {
			if v != -1 {
				indegree[v]++
				if indegree[v] > 1 {
					return false
				}
			}
		}
	}
	root := -1
	for u, d := range indegree {
		if d == 0 {
			if root != -1 {
				return false
			}
			root = u
		}
	}
	if root == -1 {
		return false
	}
	seen := make([]bool, n)
	stack := []int{root}
	count := 0
	for len(stack) > 0 {
		u := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		if seen[u] {
			return false
		}
		seen[u] = true
		count++
		for _, v := range []int{leftChild[u], rightChild[u]} {
			if v != -1 {
				stack = append(stack, v)
			}
		}
	}
	return count == n
}

