	for i := 0; i < n; i++ {
		d.parent[i] = i
		d.size[i] = 1
	}
	return d
}
func (d *dsu) find(x int) int {
	for x != d.parent[x] {
		d.parent[x] = d.parent[d.parent[x]]
		x = d.parent[x]
	}
	return x
}
func (d *dsu) union(a, b int) {
	a, b = d.find(a), d.find(b)
	if a == b {
		return
	}
	if d.size[a] < d.size[b] {
		a, b = b, a
	}
	d.parent[b] = a
	d.size[a] += d.size[b]
	d.components--
}
func removeStones(stones [][]int) int {
	d := newDSU(len(stones))
	rows, cols := map[int]int{}, map[int]int{}
	for i, s := range stones {
		r, c := s[0], s[1]
		if j, ok := rows[r]; ok {
			d.union(i, j)
		}
		if j, ok := cols[c]; ok {
			d.union(i, j)
		}
		rows[r] = i
		cols[c] = i
	}
	return len(stones) - d.components
}

