import "container/heap"

type probabilityEdge struct {
	to   int
	prob float64
}
type probabilityState struct {
	node int
	prob float64
}
type probabilityHeap []probabilityState

func (h probabilityHeap) Len() int           { return len(h) }
func (h probabilityHeap) Less(i, j int) bool { return h[i].prob > h[j].prob }
func (h probabilityHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *probabilityHeap) Push(x any)        { *h = append(*h, x.(probabilityState)) }
func (h *probabilityHeap) Pop() any          { a := *h; x := a[len(a)-1]; *h = a[:len(a)-1]; return x }
func maxProbability(n int, edges [][]int, succProb []float64, start, end int) float64 {
	g := make([][]probabilityEdge, n)
	for i, e := range edges {
		a, b := e[0], e[1]
		g[a] = append(g[a], probabilityEdge{b, succProb[i]})
		g[b] = append(g[b], probabilityEdge{a, succProb[i]})
	}
	best := make([]float64, n)
	best[start] = 1
	h := probabilityHeap{{start, 1}}
	for len(h) > 0 {
		cur := heap.Pop(&h).(probabilityState)
		if cur.prob < best[cur.node] {
			continue
		}
		if cur.node == end {
			return cur.prob
		}
		for _, e := range g[cur.node] {
			candidate := cur.prob * e.prob
			if candidate > best[e.to] {
				best[e.to] = candidate
				heap.Push(&h, probabilityState{e.to, candidate})
			}
		}
	}
	return 0
}

minimum-cost-to-make-at-least-one-valid-.go:
import "container/list"

func minCost(grid [][]int) int {
	rows, cols := len(grid), len(grid[0])
	type state struct{ r, c, cost int }
	dist := make([]int, rows*cols)
	for i := range dist {
		dist[i] = rows * cols
	}
	dist[0] = 0
	queue := list.New()
	queue.PushFront(state{0, 0, 0})
	dirs := [][2]int{{0, 1}, {0, -1}, {1, 0}, {-1, 0}}
	for queue.Len() > 0 {
		front := queue.Front()
		cur := queue.Remove(front).(state)
		id := cur.r*cols + cur.c
		if cur.cost != dist[id] {
			continue
		}
		if id == rows*cols-1 {
			return cur.cost
		}
		for d, step := range dirs {
			r, c := cur.r+step[0], cur.c+step[1]
			if r < 0 || r >= rows || c < 0 || c >= cols {
				continue
			}
			cost := 0
			if grid[cur.r][cur.c] != d+1 {
				cost = 1
			}
			next := cur.cost + cost
			at := r*cols + c
			if next < dist[at] {
				dist[at] = next
				s := state{r, c, next}
				if cost == 0 {
					queue.PushFront(s)
				} else {
					queue.PushBack(s)
				}
			}
		}
	}
	return dist[len(dist)-1]
}

