func findCheapestPrice(n int, flights [][]int, src, dst, k int) int {
	const infinity int64 = 1 << 60
	dist := make([]int64, n)
	for i := range dist {
		dist[i] = infinity
	}
	dist[src] = 0
	for round := 0; round <= k; round++ {
		next := append([]int64{}, dist...)
		for _, f := range flights {
			from, to, price := f[0], f[1], int64(f[2])
			if dist[from] != infinity {
				next[to] = min(next[to], dist[from]+price)
			}
		}
		dist = next
	}
	if dist[dst] == infinity {
		return -1
	}
	return int(dist[dst])
}

