import "container/heap"

type gap struct{ left, right int }
type gapHeap struct {
	items []gap
	n     int
}

func (h gapHeap) Len() int { return len(h.items) }
func (h gapHeap) seat(g gap) int {
	if g.left == -1 {
		return 0
	}
	if g.right == h.n {
		return h.n - 1
	}
	return g.left + (g.right-g.left)/2
}
func (h gapHeap) distance(g gap) int {
	if g.left == -1 {
		return g.right
	}
	if g.right == h.n {
		return h.n - 1 - g.left
	}
	return (g.right - g.left) / 2
}
func (h gapHeap) Less(i, j int) bool {
	a, b := h.items[i], h.items[j]
	da, db := h.distance(a), h.distance(b)
	if da != db {
		return da > db
	}
	return h.seat(a) < h.seat(b)
}
func (h gapHeap) Swap(i, j int) { h.items[i], h.items[j] = h.items[j], h.items[i] }
func (h *gapHeap) Push(x any)   { h.items = append(h.items, x.(gap)) }
func (h *gapHeap) Pop() any     { a := h.items; x := a[len(a)-1]; h.items = a[:len(a)-1]; return x }

type ExamRoom struct {
	n           int
	gaps        gapHeap
	right, left map[int]int
}

func Constructor(n int) ExamRoom {
	e := ExamRoom{n: n, gaps: gapHeap{n: n}, right: map[int]int{}, left: map[int]int{}}
	e.add(-1, n)
	return e
}
func (e *ExamRoom) add(l, r int) {
	e.right[l] = r
	e.left[r] = l
	if r-l > 1 {
		heap.Push(&e.gaps, gap{l, r})
	}
}
func (e *ExamRoom) remove(l, r int) { delete(e.right, l); delete(e.left, r) }
func (e *ExamRoom) Seat() int {
	for {
		g := heap.Pop(&e.gaps).(gap)
		r, active := e.right[g.left]
		if !active || r != g.right {
			continue
		}
		seat := e.gaps.seat(g)
		e.remove(g.left, g.right)
		e.add(g.left, seat)
		e.add(seat, g.right)
		return seat
	}
}
func (e *ExamRoom) Leave(p int) {
	l, r := e.left[p], e.right[p]
	e.remove(l, p)
	e.remove(p, r)
	e.add(l, r)
}

