type nestedFrame struct {
	items []*NestedInteger
	index int
}
type NestedIterator struct{ frames []nestedFrame }

func Constructor(nestedList []*NestedInteger) *NestedIterator {
	return &NestedIterator{frames: []nestedFrame{{items: nestedList}}}
}
func (it *NestedIterator) HasNext() bool {
	for len(it.frames) > 0 {
		top := &it.frames[len(it.frames)-1]
		if top.index == len(top.items) {
			it.frames = it.frames[:len(it.frames)-1]
			continue
		}
		item := top.items[top.index]
		if item.IsInteger() {
			return true
		}
		top.index++
		it.frames = append(it.frames, nestedFrame{items: item.GetList()})
	}
	return false
}
func (it *NestedIterator) Next() int {
	if !it.HasNext() {
		panic("iterator exhausted")
	}
	top := &it.frames[len(it.frames)-1]
	v := top.items[top.index].GetInteger()
	top.index++
	return v
}

