import "strings"

func crackSafe(n, k int) string {
	vertices := 1
	for i := 1; i < n; i++ {
		vertices *= k
	}
	nextDigit := make([]int, vertices)
	digits := []byte{}
	var walk func(int)
	walk = func(node int) {
		for nextDigit[node] < k {
			digit := nextDigit[node]
			nextDigit[node]++
			walk((node*k + digit) % vertices)
			digits = append(digits, byte('0'+digit))
		}
	}
	walk(0)
	for i, j := 0, len(digits)-1; i < j; i, j = i+1, j-1 {
		digits[i], digits[j] = digits[j], digits[i]
	}
	return strings.Repeat("0", n-1) + string(digits)
}

