func numsSameConsecDiff(n, k int) []int {
	out := []int{}
	var build func(int, int)
	build = func(value, left int) {
		if left == 0 {
			out = append(out, value)
			return
		}
		last := value % 10
		if d := last - k; d >= 0 {
			build(value*10+d, left-1)
		}
		if d := last + k; k != 0 && d <= 9 {
			build(value*10+d, left-1)
		}
	}
	for first := 1; first <= 9; first++ {
		build(first, n-1)
	}
	return out
}

