				left++
			}
			if v == 1 {
				sr, sc = r, c
			}
		}
	}
	var walk func(int, int, int) int
	walk = func(r, c, remaining int) int {
		if r < 0 || r >= rows || c < 0 || c >= cols || grid[r][c] < 0 {
			return 0
		}
		if grid[r][c] == 2 {
			if remaining == 1 {
				return 1
			}
			return 0
		}
		saved := grid[r][c]
		grid[r][c] = -1
		answer := walk(r+1, c, remaining-1) + walk(r-1, c, remaining-1) + walk(r, c+1, remaining-1) + walk(r, c-1, remaining-1)
		grid[r][c] = saved
		return answer
	}
	return walk(sr, sc, left)
}

