import "math/bits"

func countArrangement(n int) int {
	full := (1 << n) - 1
	memo := make([]int, 1<<n)
	for i := range memo {
		memo[i] = -1
	}
	var solve func(int) int
	solve = func(mask int) int {
		if mask == full {
			return 1
		}
		if memo[mask] >= 0 {
			return memo[mask]
		}
		pos := bits.OnesCount(uint(mask)) + 1
		answer := 0
		for v := 1; v <= n; v++ {
			bit := 1 << (v - 1)
			if mask&bit == 0 && (v%pos == 0 || pos%v == 0) {
				answer += solve(mask | bit)
			}
		}
		memo[mask] = answer
		return answer
	}
	return solve(0)
}

