import "sort"

func makesquare(matchsticks []int) bool {
	sum := 0
	for _, v := range matchsticks {
		sum += v
	}
	if sum%4 != 0 {
		return false
	}
	target := sum / 4
	a := append([]int{}, matchsticks...)
	sort.Sort(sort.Reverse(sort.IntSlice(a)))
	if len(a) > 0 && a[0] > target {
		return false
	}
	sides := [4]int{}
	var place func(int) bool
	place = func(at int) bool {
		if at == len(a) {
			return true
		}
		seen := map[int]bool{}
		for i := range sides {
			if seen[sides[i]] || sides[i]+a[at] > target {
				continue
			}
			seen[sides[i]] = true
			sides[i] += a[at]
			if place(at + 1) {
				return true
			}
			sides[i] -= a[at]
		}
		return false
	}
	return place(0)
}

