func getMaximumGold(grid [][]int) int {
	rows, cols := len(grid), len(grid[0])
	var walk func(int, int) int
	walk = func(r, c int) int {
		if r < 0 || r >= rows || c < 0 || c >= cols || grid[r][c] == 0 {
			return 0
		}
		value := grid[r][c]
		grid[r][c] = 0
		best := max(max(walk(r+1, c), walk(r-1, c)), max(walk(r, c+1), walk(r, c-1)))
		grid[r][c] = value
		return value + best
	}
	answer := 0
	for r := range grid {
		for c := range grid[r] {
			answer = max(answer, walk(r, c))
		}
	}
	return answer
}

