import "math/big"

func splitString(s string) bool {
	one, ten := big.NewInt(1), big.NewInt(10)
	var search func(int, *big.Int) bool
	search = func(at int, previous *big.Int) bool {
		if at == len(s) {
			return true
		}
		target := new(big.Int).Sub(previous, one)
		if target.Sign() < 0 {
			return false
		}
		value := new(big.Int)
		for end := at; end < len(s); end++ {
			value.Mul(value, ten)
			value.Add(value, big.NewInt(int64(s[end]-'0')))
			cmp := value.Cmp(target)
			if cmp > 0 {
				break
			}
			if cmp == 0 && search(end+1, value) {
				return true
			}
		}
		return false
	}
	for end := 1; end < len(s); end++ {
		first, _ := new(big.Int).SetString(s[:end], 10)
		if search(end, first) {
			return true
		}
	}
	return false
}

