func maxUniqueSplit(s string) int {
	used := map[string]bool{}
	best := 0
	var search func(int, int)
	search = func(at, count int) {
		if count+len(s)-at <= best {
			return
		}
		if at == len(s) {
			best = count
			return
		}
		for end := at + 1; end <= len(s); end++ {
			part := s[at:end]
			if used[part] {
				continue
			}
			used[part] = true
			search(end, count+1)
			delete(used, part)
		}
	}
	search(0, 0)
	return best
}

