	"sort"
)

func numSquarefulPerms(nums []int) int {
	a := append([]int{}, nums...)
	sort.Ints(a)
	n := len(a)
	adj := make([][]bool, n)
	for i := range a {
		adj[i] = make([]bool, n)
		for j := range a {
			sum := int64(a[i]) + int64(a[j])
			r := int64(math.Sqrt(float64(sum)))
			adj[i][j] = r*r == sum
		}
	}
	used := make([]bool, n)
	var search func(int, int) int
	search = func(previous, count int) int {
		if count == n {
			return 1
		}
		answer := 0
		for i := range a {
			if used[i] || (i > 0 && a[i] == a[i-1] && !used[i-1]) || (previous >= 0 && !adj[previous][i]) {
				continue
			}
			used[i] = true
			answer += search(i, count+1)
			used[i] = false
		}
		return answer
	}
	return search(-1, 0)
}

