import "fmt"

func shoppingOffers(price []int, special [][]int, needs []int) int {
	d := len(price)
	offers := [][]int{}
	for _, offer := range special {
		quantity, individual := 0, 0
		for i := 0; i < d; i++ {
			quantity += offer[i]
			individual += offer[i] * price[i]
		}
		if quantity > 0 && offer[d] < individual {
			offers = append(offers, offer)
		}
	}
	memo := map[string]int{}
	var solve func([]int) int
	solve = func(left []int) int {
		key := fmt.Sprint(left)
		if answer, ok := memo[key]; ok {
			return answer
		}
		best := 0
		for i, v := range left {
			best += v * price[i]
		}
		for _, offer := range offers {
			next := make([]int, d)
			fits := true
			for i, v := range left {
				if offer[i] > v {
					fits = false
					break
				}
				next[i] = v - offer[i]
			}
			if fits {
				best = min(best, offer[d]+solve(next))
			}
		}
		memo[key] = best
		return best
	}
	return solve(needs)
}

