import "sort"

func removeInvalidParentheses(s string) []string {
	left, right := 0, 0
	for i := range s {
		if s[i] == '(' {
			left++
		} else if s[i] == ')' {
			if left > 0 {
				left--
			} else {
				right++
			}
		}
	}
	seen := map[string]bool{}
	path := []byte{}
	var search func(int, int, int, int)
	search = func(at, l, r, balance int) {
		if l+r > len(s)-at {
			return
		}
		if at == len(s) {
			if l == 0 && r == 0 && balance == 0 {
				seen[string(path)] = true
			}
			return
		}
		ch := s[at]
		if ch == '(' && l > 0 {
			search(at+1, l-1, r, balance)
		}
		if ch == ')' && r > 0 {
			search(at+1, l, r-1, balance)
		}
		if ch == ')' && balance == 0 {
			return
		}
		path = append(path, ch)
		next := balance
		if ch == '(' {
			next++
		} else if ch == ')' {
			next--
		}
		search(at+1, l, r, next)
		path = path[:len(path)-1]
	}
	search(0, left, right, 0)
	out := make([]string, 0, len(seen))
	for v := range seen {
		out = append(out, v)
	}
	sort.Strings(out)
	return out
}

