import "math/bits"

func minimumMoves(grid [][]int) int {
	extra, empty := [][2]int{}, [][2]int{}
	for r := range grid {
		for c, v := range grid[r] {
			if v == 0 {
				empty = append(empty, [2]int{r, c})
			}
			for count := 1; count < v; count++ {
				extra = append(extra, [2]int{r, c})
			}
		}
	}
	m := len(extra)
	memo := make([]int, 1<<m)
	for i := range memo {
		memo[i] = -1
	}
	abs := func(v int) int {
		if v < 0 {
			return -v
		}
		return v
	}
	var solve func(int) int
	solve = func(mask int) int {
		if mask == (1<<m)-1 {
			return 0
		}
		if memo[mask] >= 0 {
			return memo[mask]
		}
		at := bits.OnesCount(uint(mask))
		best := 1000000
		for i, target := range empty {
			if mask&(1<<i) != 0 {
				continue
			}
			distance := abs(extra[at][0]-target[0]) + abs(extra[at][1]-target[1])
			best = min(best, distance+solve(mask|(1<<i)))
		}
		memo[mask] = best
		return best
	}
	return solve(0)
}

