import "sort"

func minimumTimeRequired(jobs []int, k int) int {
	a := append([]int{}, jobs...)
	sort.Sort(sort.Reverse(sort.IntSlice(a)))
	total := 0
	for _, v := range a {
		total += v
	}
	best := total
	lower := max(a[0], (total+k-1)/k)
	loads := make([]int, k)
	var assign func(int, int)
	assign = func(at, maximum int) {
		if best == lower {
			return
		}
		if at == len(a) {
			best = min(best, maximum)
			return
		}
		seen := map[int]bool{}
		for worker := 0; worker < k; worker++ {
			old := loads[worker]
			if seen[old] || old+a[at] >= best {
				continue
			}
			seen[old] = true
			loads[worker] += a[at]
			assign(at+1, max(maximum, loads[worker]))
			loads[worker] = old
		}
	}
	assign(0, 0)
	return best
}

