func findMinHeightTrees(n int, edges [][]int) []int {
	if n <= 2 {
		out := make([]int, n)
		for i := range out {
			out[i] = i
		}
		return out
	}
	g := make([][]int, n)
	degree := make([]int, n)
	for _, e := range edges {
		a, b := e[0], e[1]
		g[a] = append(g[a], b)
		g[b] = append(g[b], a)
		degree[a]++
		degree[b]++
	}
	leaves := []int{}
	for u, d := range degree {
		if d == 1 {
			leaves = append(leaves, u)
		}
	}
	remaining := n
	for remaining > 2 {
		remaining -= len(leaves)
		next := []int{}
		for _, u := range leaves {
			for _, v := range g[u] {
				degree[v]--
				if degree[v] == 1 {
					next = append(next, v)
				}
			}
		}
		leaves = next
	}
	return leaves
}

