func minMutation(startGene, endGene string, bank []string) int {
	if startGene == endGene {
		return 0
	}
	available := map[string]bool{}
	for _, g := range bank {
		available[g] = true
	}
	if !available[endGene] {
		return -1
	}
	delete(available, startGene)
	queue := []string{startGene}
	depth := 0
	for len(queue) > 0 {
		next := []string{}
		for _, gene := range queue {
			buffer := []byte(gene)
			for i, original := range buffer {
				for _, letter := range []byte{'A', 'C', 'G', 'T'} {
					if letter == original {
						continue
					}
					buffer[i] = letter
					candidate := string(buffer)
					if available[candidate] {
						if candidate == endGene {
							return depth + 1
						}
						delete(available, candidate)
						next = append(next, candidate)
					}
				}
				buffer[i] = original
			}
		}
		queue = next
		depth++
	}
	return -1
}

