func nearestExit(maze [][]byte, entrance []int) int {
	rows, cols := len(maze), len(maze[0])
	seen := make([]bool, rows*cols)
	sr, sc := entrance[0], entrance[1]
	seen[sr*cols+sc] = true
	queue := [][2]int{{sr, sc}}
	distance := 0
	for len(queue) > 0 {
		next := [][2]int{}
		for _, p := range queue {
			r, c := p[0], p[1]
			if (r != sr || c != sc) && (r == 0 || r == rows-1 || c == 0 || c == cols-1) {
				return distance
			}
			for _, d := range [][2]int{{0, 1}, {0, -1}, {1, 0}, {-1, 0}} {
				nr, nc := r+d[0], c+d[1]
				if nr >= 0 && nr < rows && nc >= 0 && nc < cols && maze[nr][nc] == '.' && !seen[nr*cols+nc] {
					seen[nr*cols+nc] = true
					next = append(next, [2]int{nr, nc})
				}
			}
		}
		queue = next
		distance++
	}
	return -1
}

