func minMalwareSpread(graph [][]int, initial []int) int {
	n := len(graph)
	component := make([]int, n)
	for i := range component {
		component[i] = -1
	}
	sizes := []int{}
	for start := 0; start < n; start++ {
		if component[start] >= 0 {
			continue
		}
		id := len(sizes)
		component[start] = id
		queue := []int{start}
		for at := 0; at < len(queue); at++ {
			u := queue[at]
			for v, edge := range graph[u] {
				if edge == 1 && component[v] < 0 {
					component[v] = id
					queue = append(queue, v)
				}
			}
		}
		sizes = append(sizes, len(queue))
	}
	sources := make([]int, len(sizes))
	for _, u := range initial {
		sources[component[u]]++
	}
	answer, best := initial[0], -1
	for _, u := range initial {
		saved := 0
		id := component[u]
		if sources[id] == 1 {
			saved = sizes[id]
		}
		if saved > best || (saved == best && u < answer) {
			best = saved
			answer = u
		}
	}
	return answer
}

