func maximumDetonation(bombs [][]int) int {
	n := len(bombs)
	g := make([][]int, n)
	for i, a := range bombs {
		for j, b := range bombs {
			if i == j {
				continue
			}
			dx, dy := int64(a[0])-int64(b[0]), int64(a[1])-int64(b[1])
			radius := int64(a[2])
			if dx*dx+dy*dy <= radius*radius {
				g[i] = append(g[i], j)
			}
		}
	}
	best := 0
	for start := 0; start < n; start++ {
		seen := make([]bool, n)
		seen[start] = true
		queue := []int{start}
		for at := 0; at < len(queue); at++ {
			for _, v := range g[queue[at]] {
				if !seen[v] {
					seen[v] = true
					queue = append(queue, v)
				}
			}
		}
		best = max(best, len(queue))
	}
	return best
}

