func pacificAtlantic(heights [][]int) [][]int {
	rows, cols := len(heights), len(heights[0])
	flood := func(pacific bool) []bool {
		seen := make([]bool, rows*cols)
		queue := [][2]int{}
		push := func(r, c int) {
			if !seen[r*cols+c] {
				seen[r*cols+c] = true
				queue = append(queue, [2]int{r, c})
			}
		}
		for r := 0; r < rows; r++ {
			if pacific {
				push(r, 0)
			} else {
				push(r, cols-1)
			}
		}
		for c := 0; c < cols; c++ {
			if pacific {
				push(0, c)
			} else {
				push(rows-1, c)
			}
		}
		for at := 0; at < len(queue); at++ {
			r, c := queue[at][0], queue[at][1]
			for _, d := range [][2]int{{0, 1}, {0, -1}, {1, 0}, {-1, 0}} {
				nr, nc := r+d[0], c+d[1]
				if nr >= 0 && nr < rows && nc >= 0 && nc < cols && heights[nr][nc] >= heights[r][c] {
					push(nr, nc)
				}
			}
		}
		return seen
	}
	a, b := flood(true), flood(false)
	out := [][]int{}
	for r := 0; r < rows; r++ {
		for c := 0; c < cols; c++ {
			if a[r*cols+c] && b[r*cols+c] {
				out = append(out, []int{r, c})
			}
		}
	}
	return out
}

