func canMeasureWater(x, y, target int) bool {
	if target > x+y {
		return false
	}
	type state struct{ a, b int }
	queue := []state{{0, 0}}
	seen := map[state]bool{{0, 0}: true}
	for at := 0; at < len(queue); at++ {
		s := queue[at]
		if s.a+s.b == target {
			return true
		}
		toB := min(s.a, y-s.b)
		toA := min(s.b, x-s.a)
		next := []state{{x, s.b}, {s.a, y}, {0, s.b}, {s.a, 0}, {s.a - toB, s.b + toB}, {s.a + toA, s.b - toA}}
		for _, v := range next {
			if !seen[v] {
				seen[v] = true
				queue = append(queue, v)
			}
		}
	}
	return false
}

