func calcEquation(equations [][]string, values []float64, queries [][]string) []float64 {
	type edge struct {
		to    string
		ratio float64
	}
	g := map[string][]edge{}
	for i, e := range equations {
		a, b := e[0], e[1]
		g[a] = append(g[a], edge{b, values[i]})
		g[b] = append(g[b], edge{a, 1 / values[i]})
	}
	out := make([]float64, len(queries))
	for i, q := range queries {
		out[i] = -1
		start, end := q[0], q[1]
		if _, ok := g[start]; !ok {
			continue
		}
		if _, ok := g[end]; !ok {
			continue
		}
		type state struct {
			name  string
			ratio float64
		}
		queue := []state{{start, 1}}
		seen := map[string]bool{start: true}
		for at := 0; at < len(queue); at++ {
			s := queue[at]
			if s.name == end {
				out[i] = s.ratio
				break
			}
			for _, e := range g[s.name] {
				if !seen[e.to] {
					seen[e.to] = true
					queue = append(queue, state{e.to, s.ratio * e.ratio})
				}
			}
		}
	}
	return out
}

