	for z := range dp {
		dp[z] = make([]int, n+1)
	}
	for _, s := range strs {
		zeros, ones := 0, 0
		for i := range s {
			if s[i] == '0' {
				zeros++
			} else {
				ones++
			}
		}
		for z := m; z >= zeros; z-- {
			for o := n; o >= ones; o-- {
				dp[z][o] = max(dp[z][o], dp[z-zeros][o-ones]+1)
			}
		}
	}
	return dp[m][n]
}

