	reachable := make([]bool, 2*maximum)
	reachable[0] = true
	for i, v := range a {
		if i > 0 && v == a[i-1] {
			continue
		}
		for sum := v - 1; sum >= 0; sum-- {
			if reachable[sum] {
				reachable[sum+v] = true
			}
		}
	}
	for sum := len(reachable) - 1; sum >= 0; sum-- {
