func slidingPuzzle(board [][]int) int {
	start := make([]byte, 0, 6)
	for _, row := range board {
		for _, v := range row {
			start = append(start, byte(v)+'0')
		}
	}
	neighbors := [6][]int{{1, 3}, {0, 2, 4}, {1, 5}, {0, 4}, {1, 3, 5}, {2, 4}}
	queue := []string{string(start)}
	seen := map[string]bool{string(start): true}
	head, steps := 0, 0
	for head < len(queue) {
		end := len(queue)
		for head < end {
			s := queue[head]
			head++
			if s == "123450" {
				return steps
			}
			blank := 0
			for s[blank] != '0' {
				blank++
			}
			for _, to := range neighbors[blank] {
				next := []byte(s)
				next[blank], next[to] = next[to], next[blank]
				key := string(next)
				if !seen[key] {
					seen[key] = true
					queue = append(queue, key)
				}
			}
		}
		steps++
	}
	return -1
}

