func largestDivisibleSubset(nums []int) []int {
	if len(nums) == 0 {
		return []int{}
	}
	a := append([]int{}, nums...)
	sort.Ints(a)
	dp, prev := make([]int, len(a)), make([]int, len(a))
	best := 0
	for i := range a {
		dp[i], prev[i] = 1, -1
		for j := 0; j < i; j++ {
			if a[i]%a[j] == 0 && dp[j]+1 > dp[i] {
				dp[i], prev[i] = dp[j]+1, j
			}
		}
		if dp[i] > dp[best] {
			best = i
		}
	}
	answer := []int{}
	for best != -1 {
		answer = append(answer, a[best])
		best = prev[best]
	}
	for i, j := 0, len(answer)-1; i < j; i, j = i+1, j-1 {
		answer[i], answer[j] = answer[j], answer[i]
	}
	return answer
}

