func jobScheduling(startTime, endTime, profit []int) int {
	type job struct{ start, end, reward int }
	jobs := make([]job, len(profit))
	for i := range jobs {
		jobs[i] = job{startTime[i], endTime[i], profit[i]}
	}
	sort.Slice(jobs, func(i, j int) bool { return jobs[i].end < jobs[j].end })
	dp := make([]int, len(jobs)+1)
	for i, current := range jobs {
		j := sort.Search(i, func(j int) bool { return jobs[j].end > current.start })
		dp[i+1] = max(dp[i], dp[j]+current.reward)
	}
	return dp[len(jobs)]
}

