func myAtoi(s string) int {
	i := 0
	for i < len(s) && s[i] == ' ' {
		i++
	}
	sign := int64(1)
	if i < len(s) && (s[i] == '+' || s[i] == '-') {
		if s[i] == '-' {
			sign = -1
		}
		i++
	}
	limit := int64(2147483647)
	if sign < 0 {
		limit++
	}
	value := int64(0)
	for i < len(s) && s[i] >= '0' && s[i] <= '9' {
		digit := int64(s[i] - '0')
		if value > (limit-digit)/10 {
			if sign < 0 {
				return -2147483648
			}
			return 2147483647
		}
		value = value*10 + digit
		i++
	}
	return int(sign * value)
}

