func findNthDigit(n int) int {
	remaining := int64(n)
	digits, count, start := int64(1), int64(9), int64(1)
	for remaining > digits*count {
		remaining -= digits * count
		digits++
		count *= 10
		start *= 10
	}
	number := start + (remaining-1)/digits
	s := strconv.FormatInt(number, 10)
	return int(s[(remaining-1)%digits] - '0')
}

