		sum := carry
		if i >= 0 {
			sum += int(a[i] - '0')
			i--
		}
		if j >= 0 {
			sum += int(b[j] - '0')
			j--
		}
		digits = append(digits, byte(sum%10)+'0')
		carry = sum / 10
	}
	for l, r := 0, len(digits)-1; l < r; l, r = l+1, r-1 {
