func isAdditiveNumber(num string) bool {
	n := len(num)
	for first := 1; first < n-1; first++ {
		if first > 1 && num[0] == '0' {
			break
		}
		for second := first + 1; second < n; second++ {
			if second-first > 1 && num[first] == '0' {
				break
			}
			a, b := num[:first], num[first:second]
			pos, count := second, 2
			for pos < n {
				sum := additiveDecimalSum(a, b)
				if len(sum) > n-pos || num[pos:pos+len(sum)] != sum {
					break
				}
				pos += len(sum)
				a, b = b, sum
				count++
			}
			if pos == n && count >= 3 {
				return true
			}
		}
	}
	return false
}

