import "strconv"

func splitIntoFibonacci(num string) []int {
	n := len(num)
	for first := 1; first <= 10 && first < n-1; first++ {
		if first > 1 && num[0] == '0' {
			break
		}
		a, err := strconv.ParseInt(num[:first], 10, 32)
		if err != nil {
			break
		}
		for second := first + 1; second-first <= 10 && second < n; second++ {
			if second-first > 1 && num[first] == '0' {
				break
			}
			b, err := strconv.ParseInt(num[first:second], 10, 32)
			if err != nil {
				break
			}
			sequence := []int{int(a), int(b)}
			left, right, pos := a, b, second
			for pos < n {
				sum := left + right
				if sum > 2147483647 {
					break
				}
				expected := strconv.FormatInt(sum, 10)
				if len(expected) > n-pos || num[pos:pos+len(expected)] != expected {
					break
				}
				sequence = append(sequence, int(sum))
				pos += len(expected)
				left, right = right, sum
			}
			if pos == n && len(sequence) >= 3 {
				return sequence
			}
		}
	}
	return []int{}
}

