func partition(head *ListNode, x int) *ListNode {
	small, large := &ListNode{}, &ListNode{}
	left, right := small, large
	for head != nil {
		next := head.Next
		head.Next = nil
		if head.Val < x {
			left.Next = head
			left = head
		} else {
			right.Next = head
			right = head
