func countTarget(scores []int, target int) int {
	bound := func(strict bool) int {
		left, right := 0, len(scores)
		for left < right {
			mid := left + (right-left)/2
			if scores[mid] < target || (strict && scores[mid] == target) {
				left = mid + 1
			} else {
				right = mid
			}
		}
		return left
	}
	return bound(true) - bound(false)
}

