func carPooling(trips [][]int, capacity int) bool {
	farthest := 0
	for _, t := range trips {
		farthest = max(farthest, t[2])
	}
	events := make([]int, farthest+1)
	for _, t := range trips {
		events[t[1]] += t[0]
		events[t[2]] -= t[0]
	}
	passengers := 0
	for _, change := range events {
		passengers += change
		if passengers > capacity {
			return false
		}
	}
	return true
}

