type Checkout struct{ items, candidates *list.List }

func Constructor() Checkout { return Checkout{list.New(), list.New()} }
func (c *Checkout) Get_max() int {
	if c.candidates.Len() == 0 {
		return -1
	}
	return c.candidates.Front().Value.(int)
}
func (c *Checkout) Add(value int) {
	c.items.PushBack(value)
	for c.candidates.Len() > 0 && c.candidates.Back().Value.(int) < value {
		c.candidates.Remove(c.candidates.Back())
	}
	c.candidates.PushBack(value)
}
func (c *Checkout) Remove() int {
	if c.items.Len() == 0 {
		return -1
	}
	value := c.items.Remove(c.items.Front()).(int)
	if c.candidates.Front().Value.(int) == value {
		c.candidates.Remove(c.candidates.Front())
	}
	return value
}

