type NumArray struct {
	n    int
	tree []int
}

func Constructor(nums []int) NumArray {
	n := len(nums)
	tree := make([]int, 2*n)
	copy(tree[n:], nums)
	for i := n - 1; i > 0; i-- {
		tree[i] = tree[2*i] + tree[2*i+1]
	}
	return NumArray{n, tree}
}
func (a *NumArray) Update(index, val int) {
	p := index + a.n
	a.tree[p] = val
	for p /= 2; p > 0; p /= 2 {
		a.tree[p] = a.tree[2*p] + a.tree[2*p+1]
	}
}
func (a *NumArray) SumRange(left, right int) int {
	sum := 0
	for left, right = left+a.n, right+a.n+1; left < right; left, right = left/2, right/2 {
		if left%2 == 1 {
			sum += a.tree[left]
			left++
		}
		if right%2 == 1 {
			right--
			sum += a.tree[right]
		}
	}
	return sum
}

