func calculate(s string) int {
	total, last, number := 0, 0, 0
	op := byte('+')
	for i := 0; i <= len(s); i++ {
		c := byte('+')
		if i < len(s) {
			c = s[i]
			if c == ' ' {
				continue
			}
			if c >= '0' && c <= '9' {
				number = number*10 + int(c-'0')
				continue
			}
		}
		switch op {
		case '+':
			total += last
			last = number
		case '-':
			total += last
			last = -number
		case '*':
			last *= number
		case '/':
			last /= number
		}
		op = c
		number = 0
	}
	return total + last
}

