func calculate(s string) int {
	position := 0
	skip := func() {
		for position < len(s) && s[position] == ' ' {
			position++
		}
	}
	var expression, term, factor func() int
	factor = func() int {
		skip()
		sign := 1
		for position < len(s) && (s[position] == '+' || s[position] == '-') {
			if s[position] == '-' {
				sign = -sign
			}
			position++
			skip()
		}
		value := 0
		if position < len(s) && s[position] == '(' {
			position++
			value = expression()
			skip()
			position++
		} else {
			for position < len(s) && s[position] >= '0' && s[position] <= '9' {
				value = value*10 + int(s[position]-'0')
				position++
			}
		}
		return sign * value
	}
	term = func() int {
		value := factor()
		for {
			skip()
			if position >= len(s) || (s[position] != '*' && s[position] != '/') {
				break
			}
			op := s[position]
			position++
			right := factor()
			if op == '*' {
				value *= right
			} else {
				value /= right
			}
		}
		return value
	}
	expression = func() int {
		value := term()
		for {
			skip()
			if position >= len(s) || (s[position] != '+' && s[position] != '-') {
				break
			}
			op := s[position]
			position++
			right := term()
			if op == '+' {
				value += right
			} else {
				value -= right
			}
		}
		return value
	}
	return expression()
}

