func isBipartite(graph [][]int) bool {
	color := make([]int, len(graph))
	for start := range graph {
		if color[start] != 0 {
			continue
		}
		color[start] = 1
		queue := []int{start}
		for head := 0; head < len(queue); head++ {
			v := queue[head]
			for _, to := range graph[v] {
				if color[to] == 0 {
					color[to] = -color[v]
					queue = append(queue, to)
				} else if color[to] == color[v] {
					return false
				}
			}
		}
	}
	return true
}

