import "sort"

func minimumCost(n int, connections [][]int) int {
	if n == 1 {
		return 0
	}
	edges := append([][]int{}, connections...)
	sort.Slice(edges, func(i, j int) bool { return edges[i][2] < edges[j][2] })
	parent, size := make([]int, n+1), make([]int, n+1)
	for i := range parent {
		parent[i] = i
		size[i] = 1
	}
	find := func(x int) int {
		for x != parent[x] {
			parent[x] = parent[parent[x]]
			x = parent[x]
		}
		return x
	}
	cost, used := 0, 0
	for _, edge := range edges {
		a, b := find(edge[0]), find(edge[1])
		if a == b {
			continue
		}
		if size[a] < size[b] {
			a, b = b, a
		}
		parent[b] = a
		size[a] += size[b]
		cost += edge[2]
		used++
		if used == n-1 {
			return cost
		}
	}
	return -1
}

