func minCostConnectPoints(points [][]int) int {
	n := len(points)
	if n == 0 {
		return 0
	}
	best := make([]int, n)
	used := make([]bool, n)
	for i := 1; i < n; i++ {
		best[i] = int(^uint(0) >> 1)
	}
	absolute := func(x int) int {
		if x < 0 {
			return -x
		}
		return x
	}
	total := 0
	for count := 0; count < n; count++ {
		v := -1
		for i := 0; i < n; i++ {
			if !used[i] && (v == -1 || best[i] < best[v]) {
				v = i
			}
		}
		used[v] = true
		total += best[v]
		for to := 0; to < n; to++ {
			if !used[to] {
				distance := absolute(points[v][0]-points[to][0]) + absolute(points[v][1]-points[to][1])
				best[to] = min(best[to], distance)
			}
		}
	}
	return total
}

find-the-city-with-the-smallest-number-o.go:
func findTheCity(n int, edges [][]int, distanceThreshold int) int {
	distance := make([][]int, n)
	for i := 0; i < n; i++ {
		distance[i] = make([]int, n)
		for j := 0; j < n; j++ {
			if i != j {
				distance[i][j] = distanceThreshold + 1
			}
		}
	}
	for _, e := range edges {
		a, b, w := e[0], e[1], e[2]
		distance[a][b] = min(distance[a][b], w)
		distance[b][a] = min(distance[b][a], w)
	}
	for k := 0; k < n; k++ {
		for i := 0; i < n; i++ {
			for j := 0; j < n; j++ {
				distance[i][j] = min(distance[i][j], distance[i][k]+distance[k][j])
			}
		}
	}
	answer, fewest := -1, n+1
	for i := 0; i < n; i++ {
		count := 0
		for j := 0; j < n; j++ {
			if i != j && distance[i][j] <= distanceThreshold {
				count++
			}
		}
		if count <= fewest {
			answer, fewest = i, count
		}
	}
	return answer
}

