func maxEnvelopes(envelopes [][]int) int {
	a := append([][]int{}, envelopes...)
	sort.Slice(a, func(i, j int) bool {
		if a[i][0] != a[j][0] {
			return a[i][0] < a[j][0]
		}
		return a[i][1] > a[j][1]
	})
	tails := []int{}
	for _, e := range a {
		p := sort.SearchInts(tails, e[1])
		if p == len(tails) {
			tails = append(tails, e[1])
		} else {
			tails[p] = e[1]
		}
	}
	return len(tails)
}

