func minFallingPathSum(matrix [][]int) int {
	prev := append([]int{}, matrix[0]...)
	for row := 1; row < len(matrix); row++ {
		current := make([]int, len(prev))
		for col, value := range matrix[row] {
			best := prev[col]
			if col > 0 {
				best = min(best, prev[col-1])
			}
			if col+1 < len(prev) {
				best = min(best, prev[col+1])
			}
			current[col] = best + value
		}
		prev = current
	}
	answer := prev[0]
	for _, value := range prev {
		answer = min(answer, value)
	}
	return answer
}

