func wordBreak(s string, wordDict []string) []string {
	dictionary := map[string]bool{}
	for _, word := range wordDict {
		dictionary[word] = true
	}
	memo := map[int][]string{}
	var dfs func(int) []string
	dfs = func(start int) []string {
		if start == len(s) {
			return []string{""}
		}
		if answer, ok := memo[start]; ok {
			return answer
		}
		answer := []string{}
		for end := start + 1; end <= len(s); end++ {
			word := s[start:end]
			if !dictionary[word] {
				continue
			}
			for _, suffix := range dfs(end) {
				sentence := word
				if suffix != "" {
					sentence += " " + suffix
				}
				answer = append(answer, sentence)
			}
		}
		memo[start] = answer
		return answer
	}
	return dfs(0)
}

