func minDistance(word1, word2 string) int {
	dp := make([]int, len(word2)+1)
	for j := range dp {
		dp[j] = j
	}
	for i := 1; i <= len(word1); i++ {
		diagonal := dp[0]
		dp[0] = i
		for j := 1; j <= len(word2); j++ {
			top := dp[j]
			if word1[i-1] == word2[j-1] {
				dp[j] = diagonal
			} else {
				dp[j] = 1 + min(dp[j], dp[j-1])
			}
			diagonal = top
		}
	}
	return dp[len(word2)]
}

