func minInsertions(s string) int {
	n := len(s)
	if n < 2 {
		return 0
	}
	dp := make([]int, n)
	for i := n - 2; i >= 0; i-- {
		diagonal := 0
		for j := i + 1; j < n; j++ {
			old := dp[j]
			if s[i] == s[j] {
				dp[j] = diagonal
			} else {
				dp[j] = 1 + min(dp[j], dp[j-1])
			}
			diagonal = old
		}
	}
	return dp[n-1]
}

