func findTargetSumWays(nums []int, target int) int {
	sum := 0
	for _, v := range nums {
		sum += v
	}
	if target > sum || target < -sum || (sum+target)%2 != 0 {
		return 0
	}
	positive := (sum + target) / 2
	dp := make([]int, positive+1)
	dp[0] = 1
	for _, v := range nums {
		for j := positive; j >= v; j-- {
			dp[j] += dp[j-v]
		}
	}
	return dp[positive]
}

