func stoneGame(piles []int) bool {
	if len(piles) == 0 {
		return false
	}
	dp := append([]int{}, piles...)
	for left := len(piles) - 2; left >= 0; left-- {
		for right := left + 1; right < len(piles); right++ {
			dp[right] = max(piles[left]-dp[right], piles[right]-dp[right-1])
		}
	}
	return dp[len(piles)-1] > 0
}

