func rob(nums []int) int {
	n := len(nums)
	if n == 0 {
		return 0
	}
	if n == 1 {
		return nums[0]
	}
	linear := func(a []int) int {
		before, previous := 0, 0
		for _, value := range a {
			before, previous = previous, max(previous, before+value)
		}
		return previous
	}
	return max(linear(nums[:n-1]), linear(nums[1:]))
}

