func rob(root *TreeNode) int {
	var visit func(*TreeNode) [2]int
	visit = func(node *TreeNode) [2]int {
		if node == nil {
			return [2]int{0, 0}
		}
		left, right := visit(node.Left), visit(node.Right)
		skip := max(left[0], left[1]) + max(right[0], right[1])
		take := node.Val + left[0] + right[0]
		return [2]int{skip, take}
	}
	answer := visit(root)
	return max(answer[0], answer[1])
}

