func maxProfit(k int, prices []int) int {
	n := len(prices)
	if n == 0 || k == 0 {
		return 0
	}
	if k >= n/2 {
		answer := 0
		for i := 1; i < n; i++ {
			answer += max(0, prices[i]-prices[i-1])
		}
		return answer
	}
	cash, hold := make([]int, k+1), make([]int, k+1)
	for t := 1; t <= k; t++ {
		hold[t] = -prices[0]
	}
	for _, price := range prices[1:] {
		for t := k; t >= 1; t-- {
			cash[t] = max(cash[t], hold[t]+price)
			hold[t] = max(hold[t], cash[t-1]-price)
		}
	}
	return cash[k]
}

