func rotateRight(head *ListNode, k int) *ListNode {
	if head == nil {
		return nil
	}
	n := 1
	tail := head
	for tail.Next != nil {
		tail = tail.Next
		n++
	}
	k %= n
	if k == 0 {
		return head
	}
	newTail := head
	for i := 0; i < n-k-1; i++ {
		newTail = newTail.Next
	}
	newHead := newTail.Next
	tail.Next = head
	newTail.Next = nil
	return newHead
}

