func generateMatrix(n int) [][]int {
	a := make([][]int, n)
	for i := range a {
		a[i] = make([]int, n)
	}
	top, bottom, left, right := 0, n-1, 0, n-1
	value := 1
	for top <= bottom && left <= right {
		for c := left; c <= right; c++ {
			a[top][c] = value
			value++
		}
		top++
		for r := top; r <= bottom; r++ {
			a[r][right] = value
			value++
		}
		right--
		if top <= bottom {
			for c := right; c >= left; c-- {
				a[bottom][c] = value
				value++
			}
			bottom--
		}
		if left <= right {
			for r := bottom; r >= top; r-- {
				a[r][left] = value
				value++
			}
			left++
		}
	}
	return a
}

