import "sort"

func fourSum(nums []int, target int) [][]int {
	a := append([]int(nil), nums...)
	sort.Ints(a)
	answer := [][]int{}
	n := len(a)
	for i := 0; i < n-3; i++ {
		if i > 0 && a[i] == a[i-1] {
			continue
		}
		for j := i + 1; j < n-2; j++ {
			if j > i+1 && a[j] == a[j-1] {
				continue
			}
			l, r := j+1, n-1
			for l < r {
				sum := int64(a[i]) + int64(a[j]) + int64(a[l]) + int64(a[r])
				if sum < int64(target) {
					l++
				} else if sum > int64(target) {
					r--
				} else {
					answer = append(answer, []int{a[i], a[j], a[l], a[r]})
					x, y := a[l], a[r]
					for l < r && a[l] == x {
						l++
					}
					for l < r && a[r] == y {
						r--
					}
				}
			}
		}
	}
	return answer
}

