	answer := []string{}
	seen := map[int]int{}
	code := 0
	for i := 0; i < len(s); i++ {
		value := 0
		switch s[i] {
		case 'C':
			value = 1
		case 'G':
			value = 2
		case 'T':
			value = 3
		}
		code = ((code << 2) | value) & ((1 << 20) - 1)
		if i >= 9 {
