func sortArray(nums []int) []int {
	a := append([]int{}, nums...)
	buffer := make([]int, len(a))
	for width := 1; width < len(a); width *= 2 {
		for l := 0; l < len(a); l += 2 * width {
			m, r := min(l+width, len(a)), min(l+2*width, len(a))
			i, j := l, m
			for pos := l; pos < r; pos++ {
				if i < m && (j >= r || a[i] <= a[j]) {
					buffer[pos] = a[i]
					i++
				} else {
					buffer[pos] = a[j]
					j++
				}
			}
		}
		a, buffer = buffer, a
	}
	return a
}

