func countSmaller(nums []int) []int {
	n := len(nums)
	order, buffer, answer := make([]int, n), make([]int, n), make([]int, n)
	for i := range order {
		order[i] = i
	}
	var merge func(int, int)
	merge = func(l, r int) {
		if r-l <= 1 {
			return
		}
		m := (l + r) / 2
		merge(l, m)
		merge(m, r)
		i, j, moved := l, m, 0
		for pos := l; pos < r; pos++ {
			if i < m && (j >= r || nums[order[i]] <= nums[order[j]]) {
				answer[order[i]] += moved
				buffer[pos] = order[i]
				i++
			} else {
				moved++
				buffer[pos] = order[j]
				j++
			}
		}
		copy(order[l:r], buffer[l:r])
	}
	merge(0, n)
	return answer
}

