func reversePairs(nums []int) int {
	a := make([]int64, len(nums))
	for i, v := range nums {
		a[i] = int64(v)
	}
	buffer := make([]int64, len(a))
	var solve func(int, int) int
	solve = func(l, r int) int {
		if r-l <= 1 {
			return 0
		}
		m := (l + r) / 2
		count := solve(l, m) + solve(m, r)
		j := m
		for i := l; i < m; i++ {
			for j < r && a[i] > 2*a[j] {
				j++
			}
			count += j - m
		}
		i, k := l, m
		for pos := l; pos < r; pos++ {
			if i < m && (k >= r || a[i] <= a[k]) {
				buffer[pos] = a[i]
				i++
			} else {
				buffer[pos] = a[k]
				k++
			}
		}
		copy(a[l:r], buffer[l:r])
		return count
	}
	return solve(0, len(a))
}

