func countRangeSum(nums []int, lower, upper int) int {
	prefix := make([]int64, len(nums)+1)
	for i, v := range nums {
		prefix[i+1] = prefix[i] + int64(v)
	}
	buffer := make([]int64, len(prefix))
	lo, hi := int64(lower), int64(upper)
	var solve func(int, int) int
	solve = func(l, r int) int {
		if r-l <= 1 {
			return 0
		}
		m := (l + r) / 2
		count := solve(l, m) + solve(m, r)
		low, high := m, m
		for i := l; i < m; i++ {
			for low < r && prefix[low]-prefix[i] < lo {
				low++
			}
			for high < r && prefix[high]-prefix[i] <= hi {
				high++
			}
			count += high - low
		}
		i, j := l, m
		for pos := l; pos < r; pos++ {
			if i < m && (j >= r || prefix[i] <= prefix[j]) {
				buffer[pos] = prefix[i]
				i++
			} else {
				buffer[pos] = prefix[j]
				j++
			}
		}
		copy(prefix[l:r], buffer[l:r])
		return count
	}
	return solve(0, len(prefix))
}

lfu-cache.go:
import "container/list"

type lfuEntry struct {
	key, value, freq int
	node             *list.Element
}
type LFUCache struct {
	capacity, minFreq int
	items             map[int]*lfuEntry
	buckets           map[int]*list.List
}

func Constructor(capacity int) LFUCache {
	return LFUCache{capacity: capacity, items: map[int]*lfuEntry{}, buckets: map[int]*list.List{}}
}
func (c *LFUCache) touch(e *lfuEntry) {
	old := c.buckets[e.freq]
	old.Remove(e.node)
	if old.Len() == 0 {
		delete(c.buckets, e.freq)
		if c.minFreq == e.freq {
			c.minFreq++
		}
	}
	e.freq++
	bucket := c.buckets[e.freq]
	if bucket == nil {
		bucket = list.New()
		c.buckets[e.freq] = bucket
	}
	e.node = bucket.PushFront(e)
}
func (c *LFUCache) Get(key int) int {
	e := c.items[key]
	if e == nil {
		return -1
	}
	c.touch(e)
	return e.value
}
func (c *LFUCache) Put(key, value int) {
	if c.capacity == 0 {
		return
	}
	if e := c.items[key]; e != nil {
		e.value = value
		c.touch(e)
		return
	}
	if len(c.items) == c.capacity {
		bucket := c.buckets[c.minFreq]
		node := bucket.Back()
		e := node.Value.(*lfuEntry)
		delete(c.items, e.key)
		bucket.Remove(node)
		if bucket.Len() == 0 {
			delete(c.buckets, c.minFreq)
		}
	}
	bucket := c.buckets[1]
	if bucket == nil {
		bucket = list.New()
		c.buckets[1] = bucket
	}
	e := &lfuEntry{key: key, value: value, freq: 1}
	e.node = bucket.PushFront(e)
	c.items[key] = e
	c.minFreq = 1
}

