func totalNQueens(n int) int {
	mask := (uint(1) << n) - 1
	var visit func(uint, uint, uint) int
	visit = func(cols, left, right uint) int {
		if cols == mask {
			return 1
		}
		available := mask &^ (cols | left | right)
		count := 0
		for available != 0 {
			bit := available & -available
			available -= bit
			count += visit(cols|bit, ((left|bit)<<1)&mask, (right|bit)>>1)
		}
		return count
	}
	return visit(0, 0, 0)
}

