func closedIsland(grid [][]int) int {
	m, n := len(grid), len(grid[0])
	seen := make([][]bool, m)
	for i := range seen {
		seen[i] = make([]bool, n)
	}
	answer := 0
	directions := [][2]int{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}
	for r := 0; r < m; r++ {
		for c := 0; c < n; c++ {
			if grid[r][c] != 0 || seen[r][c] {
				continue
			}
			queue := [][2]int{{r, c}}
			seen[r][c] = true
			closed := true
			for h := 0; h < len(queue); h++ {
				x, y := queue[h][0], queue[h][1]
				if x == 0 || x == m-1 || y == 0 || y == n-1 {
					closed = false
				}
				for _, d := range directions {
					a, b := x+d[0], y+d[1]
					if a >= 0 && a < m && b >= 0 && b < n && grid[a][b] == 0 && !seen[a][b] {
						seen[a][b] = true
						queue = append(queue, [2]int{a, b})
					}
				}
			}
			if closed {
				answer++
			}
		}
	}
	return answer
}

