import "sort"

func canPartitionKSubsets(nums []int, k int) bool {
	if k <= 0 || k > len(nums) {
		return false
	}
	total := 0
	for _, v := range nums {
		total += v
	}
	if total%k != 0 {
		return false
	}
	target := total / k
	a := append([]int(nil), nums...)
	sort.Sort(sort.Reverse(sort.IntSlice(a)))
	if a[0] > target {
		return false
	}
	buckets := make([]int, k)
	var assign func(int) bool
	assign = func(index int) bool {
		if index == len(a) {
			return true
		}
		tried := map[int]bool{}
		for i := range buckets {
			load := buckets[i]
			if tried[load] || load+a[index] > target {
				continue
			}
			tried[load] = true
			buckets[i] += a[index]
			if assign(index + 1) {
				return true
			}
			buckets[i] -= a[index]
			if load == 0 {
				break
			}
		}
		return false
	}
	return assign(0)
}

