import "sort"

func removeCoveredIntervals(intervals [][]int) int {
	a := append([][]int(nil), intervals...)
	sort.Slice(a, func(i, j int) bool {
		if a[i][0] != a[j][0] {
			return a[i][0] < a[j][0]
		}
		return a[i][1] > a[j][1]
	})
	answer, farthest := 0, 0
	for _, interval := range a {
		if answer == 0 || interval[1] > farthest {
			answer++
			farthest = interval[1]
		}
	}
	return answer
}

