func intervalIntersection(firstList, secondList [][]int) [][]int {
	answer := [][]int{}
	for i, j := 0, 0; i < len(firstList) && j < len(secondList); {
		a, b := firstList[i], secondList[j]
		l, r := max(a[0], b[0]), min(a[1], b[1])
		if l <= r {
			answer = append(answer, []int{l, r})
		}
		if a[1] < b[1] {
			i++
		} else {
			j++
		}
	}
	return answer
}

