	for i, v := range nums {
		answer ^= i ^ v
	}
	return answer
}

shuffle-an-array.go:
import "math/rand"

type Solution struct{ original []int }

func Constructor(nums []int) Solution { return Solution{original: append([]int(nil), nums...)} }
func (s *Solution) Reset() []int      { return append([]int{}, s.original...) }
func (s *Solution) Shuffle() []int {
	a := append([]int{}, s.original...)
	for i := len(a) - 1; i > 0; i-- {
		j := rand.Intn(i + 1)
		a[i], a[j] = a[j], a[i]
	}
	return a
}

