import "math/rand"

type Solution struct{ head *ListNode }

func Constructor(head *ListNode) Solution { return Solution{head: head} }
func (s *Solution) GetRandom() int {
	answer, seen := 0, 0
	for node := s.head; node != nil; node = node.Next {
		seen++
		if rand.Intn(seen) == 0 {
			answer = node.Val
		}
	}
	return answer
}

