import "math/rand"

type Solution struct{ nums []int }

func Constructor(nums []int) Solution { return Solution{nums: append([]int(nil), nums...)} }
func (s *Solution) Pick(target int) int {
	answer, matches := -1, 0
	for i, v := range s.nums {
		if v == target {
			matches++
			if rand.Intn(matches) == 0 {
				answer = i
			}
		}
	}
	return answer
}

