func countPrimes(n int) int {
	if n <= 2 {
		return 0
	}
	composite := make([]bool, n)
	for p := 2; p <= (n-1)/p; p++ {
		if !composite[p] {
			for multiple := p * p; multiple < n; multiple += p {
				composite[multiple] = true
			}
		}
	}
	answer := 0
	for v := 2; v < n; v++ {
		if !composite[v] {
			answer++
		}
	}
	return answer
}

