func isUgly(n int) bool {
	if n <= 0 {
		return false
	}
	for _, factor := range []int{2, 3, 5} {
		for n%factor == 0 {
			n /= factor
		}
	}
	return n == 1
}

ugly-number-ii.go:
func nthUglyNumber(n int) int {
	ugly := make([]int64, n)
	ugly[0] = 1
	i2, i3, i5 := 0, 0, 0
	for i := 1; i < n; i++ {
		a, b, c := 2*ugly[i2], 3*ugly[i3], 5*ugly[i5]
		value := min(a, min(b, c))
		ugly[i] = value
		if a == value {
			i2++
		}
		if b == value {
			i3++
		}
		if c == value {
			i5++
		}
	}
	return int(ugly[n-1])
}

ugly-number-iii.go:
func nthUglyNumber(n, a, b, c int) int {
	aa, bb, cc := int64(a), int64(b), int64(c)
	upper := int64(n) * min(aa, min(bb, cc))
	gcd := func(x, y int64) int64 {
		for y != 0 {
			x, y = y, x%y
		}
		return x
	}
	lcm := func(x, y int64) int64 {
		if x > upper || y > upper {
			return upper + 1
		}
		factor := x / gcd(x, y)
		if factor > upper/y {
			return upper + 1
		}
		return factor * y
	}
	ab, ac, bc := lcm(aa, bb), lcm(aa, cc), lcm(bb, cc)
	abc := lcm(ab, cc)
	l, r := int64(1), upper
	for l < r {
		m := l + (r-l)/2
		count := m/aa + m/bb + m/cc - m/ab - m/ac - m/bc + m/abc
		if count >= int64(n) {
			r = m
		} else {
			l = m + 1
		}
	}
	return int(l)
}
